def _sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def _sha256_file(path: Path) -> str:
    return _sha256(path.read_bytes())


def _canonical_json_bytes(value: object) -> bytes:
    return (
        json.dumps(value, ensure_ascii=False, indent=2, sort_keys=True) + "\n"
    ).encode("utf-8")


def _cfg_code_aggregate(claims: Iterable[dict[str, Any]]) -> dict[str, Any]:
    """Build fail-closed bounded-CFG totals from one frozen kind registry."""

    rows = [claim for claim in claims if claim.get("role") == "primary"]
    stable_thumb_kinds = frozenset(CFG_CODE_KIND_REGISTRY["thumb_only"])
    staged_thumb_kinds = frozenset(
        CFG_STAGED_CODE_KIND_REGISTRY["thumb_only"]
    )
    arm_kinds = frozenset(CFG_CODE_KIND_REGISTRY["arm_only"])
    mixed_splits = CFG_CODE_KIND_REGISTRY["mixed"]
    mixed_kinds = frozenset(mixed_splits)
    producer_kinds = frozenset(CFG_CODE_KIND_REGISTRY["producer_only"])
    excluded_code_kinds = frozenset(
        CFG_CODE_KIND_REGISTRY["excluded_code_like"]
    )
    excluded_producer_kinds = frozenset(
        CFG_CODE_KIND_REGISTRY["excluded_producer_like"]
    )
    stable_registered_code_kinds = (
        stable_thumb_kinds | arm_kinds | mixed_kinds
    )

    def has_semantic_token(claim: dict[str, Any], token: str) -> bool:
        return any(
            token in str(claim.get(field, "")).lower().split("_")
            for field in ("claim_kind", "primary_class")
        )

    observed_code_like_kinds = {
        str(claim.get("claim_kind"))
        for claim in rows
        if has_semantic_token(claim, "code")
        or has_semantic_token(claim, "instruction")
    }
    active_staged_thumb_kinds = staged_thumb_kinds & observed_code_like_kinds
    thumb_kinds = stable_thumb_kinds | active_staged_thumb_kinds
    registered_code_kinds = stable_registered_code_kinds | active_staged_thumb_kinds
    expected_code_like_kinds = (
        stable_registered_code_kinds
        | excluded_code_kinds
        | active_staged_thumb_kinds
    )
    if observed_code_like_kinds != expected_code_like_kinds:
        missing = sorted(expected_code_like_kinds - observed_code_like_kinds)
        extra = sorted(observed_code_like_kinds - expected_code_like_kinds)
        raise ValueError(
            "bounded CFG code kind denominator changed: "
            f"missing={missing}, extra={extra}"
        )

    observed_producer_like_kinds = {
        str(claim.get("claim_kind"))
        for claim in rows
        if has_semantic_token(claim, "producer")
    }
    expected_producer_like_kinds = producer_kinds | excluded_producer_kinds
    if observed_producer_like_kinds != expected_producer_like_kinds:
        missing = sorted(expected_producer_like_kinds - observed_producer_like_kinds)
        extra = sorted(observed_producer_like_kinds - expected_producer_like_kinds)
        raise ValueError(
            "bounded CFG producer kind denominator changed: "
            f"missing={missing}, extra={extra}"
        )

    by_kind: dict[str, list[dict[str, Any]]] = {}
    for claim in rows:
        kind = str(claim.get("claim_kind"))
        if kind in registered_code_kinds | producer_kinds:
            by_kind.setdefault(kind, []).append(claim)

    for kind in thumb_kinds - {"boot_interwork_thumb_instruction_bytes"}:
        if any(claim.get("mode") != "thumb" for claim in by_kind[kind]):
            raise ValueError(f"bounded CFG Thumb mode changed for {kind}")
    if any(
        claim.get("mode") not in {None, "arm"}
        for kind in arm_kinds
        for claim in by_kind[kind]
    ):
        raise ValueError("bounded CFG ARM mode changed")
    if any(
        claim.get("mode") != "thumb"
        for kind in producer_kinds
        for claim in by_kind[kind]
    ):
        raise ValueError("bounded CFG producer mode changed")

    def kind_bytes(kind: str) -> int:
        return sum(
            claim["range"][1] - claim["range"][0]
            for claim in by_kind[kind]
        )

    for kind, split in mixed_splits.items():
        expected = split["arm_bytes"] + split["thumb_bytes"]
        if kind_bytes(kind) != expected:
            raise ValueError(f"bounded CFG mixed-mode projection changed for {kind}")
    if any(
        claim.get("mode") is not None
        for claim in by_kind["directsound_pitch_high32_interwork_instruction_bytes"]
    ):
        raise ValueError("DirectSound mixed-mode marker changed")
    if any(
        claim.get("mode") != "mixed_arm_thumb_relocated"
        for claim in by_kind["soundmain_relocated_reachable_instruction_bytes"]
    ):
        raise ValueError("SoundMain mixed-mode marker changed")

    thumb_bytes = sum(kind_bytes(kind) for kind in thumb_kinds) + sum(
        split["thumb_bytes"] for split in mixed_splits.values()
    )
    arm_bytes = sum(kind_bytes(kind) for kind in arm_kinds) + sum(
        split["arm_bytes"] for split in mixed_splits.values()
    )
    producer_bytes = sum(kind_bytes(kind) for kind in producer_kinds)
    registry_receipt: Any = CFG_CODE_KIND_REGISTRY
    if active_staged_thumb_kinds:
        registry_receipt = {
            "stable": CFG_CODE_KIND_REGISTRY,
            "active_staged_thumb_only": sorted(active_staged_thumb_kinds),
        }
    registry_sha256 = _sha256(
        json.dumps(
            registry_receipt,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    )
    return {
        "cfg_reachable_arm_code_bytes": arm_bytes,
        "cfg_reachable_thumb_code_bytes": thumb_bytes,
        "cfg_promoted_unknown_bytes": arm_bytes + thumb_bytes + producer_bytes,
        "cfg_primary_claim_count": sum(
            len(by_kind[kind]) for kind in registered_code_kinds | producer_kinds
        ),
        "cfg_code_claim_kind_count": len(registered_code_kinds),
        "cfg_code_claim_kind_denominator_sha256": registry_sha256,
    }


def _checked_repository_file(
    root: Path,
    relative: Path,
    expected_sha256: str,
    *,
    expected_size: int | None = None,
    label: str,
) -> Path:
    """Resolve and identity-check one frozen repository file without symlinks."""

    path = (root / relative).absolute()
    try:
        resolved = path.resolve(strict=True)
        resolved.relative_to(root)
    except (OSError, ValueError) as error:
        raise ValueError(f"{label} is missing or outside the repository") from error
    if resolved != path or path.is_symlink() or not path.is_file():
        raise ValueError(f"{label} uses a symlink or is not a file")
    if expected_size is not None and path.stat().st_size != expected_size:
        raise ValueError(f"{label} identity changed")
    if _sha256_file(path) != expected_sha256:
        raise ValueError(f"{label} identity changed")
    return path


def _checked_artifact_directory(
    root: Path,
    relative: Path,
    expected_files: set[str],
    *,
    label: str,
) -> Path:
    """Resolve a frozen artifact and reject foreign members and symlinks."""

    artifact = (root / relative).absolute()
    try:
        resolved = artifact.resolve(strict=True)
        resolved.relative_to(root)
    except (OSError, ValueError) as error:
        raise ValueError(f"{label} is missing or outside the repository") from error
    if resolved != artifact or artifact.is_symlink() or not artifact.is_dir():
        raise ValueError(f"{label} uses a symlink or is not a directory")
    members = list(artifact.iterdir())
    if (
        {member.name for member in members} != expected_files
        or any(member.is_symlink() or not member.is_file() for member in members)
    ):
        raise ValueError(f"{label} file set changed")
    return artifact


def _validated_range(claim: dict[str, Any], domain_end: int) -> tuple[int, int]:
    value = claim.get("range")
    if (
        not isinstance(value, list)
        or len(value) != 2
        or not all(isinstance(item, int) for item in value)
    ):
        raise ValueError(f"claim {claim.get('id')!r} has an invalid range")
    start, end = value
    if start < 0 or start >= end or end > domain_end:
        raise ValueError(f"claim {claim.get('id')!r} is outside the ROM domain")
    return start, end


def atomize_claims(
    domain_end: int, claims: Iterable[dict[str, Any]]
) -> list[dict[str, Any]]:
    """Turn possibly adjacent claims into gap-free, half-open ROM segments."""

    if not isinstance(domain_end, int) or domain_end <= 0:
        raise ValueError("domain_end must be a positive integer")
    normalized = list(claims)
    identifiers = [claim.get("id") for claim in normalized]
    if any(not isinstance(identifier, str) or not identifier for identifier in identifiers):
        raise ValueError("every claim must have a non-empty string id")
    if len(set(identifiers)) != len(identifiers):
        raise ValueError("claim ids must be unique")

    count = len(normalized)
    starts: list[int] = [0] * count
    ends: list[int] = [0] * count
    endpoints = {0, domain_end}
    for index, claim in enumerate(normalized):
        role = claim.get("role")
        if role not in {"primary", "secondary"}:
            raise ValueError(f"claim {claim['id']!r} has an invalid role")
        if role == "primary" and not isinstance(claim.get("primary_class"), str):
            raise ValueError(f"primary claim {claim['id']!r} has no class")
        start, end = _validated_range(claim, domain_end)
        starts[index] = start
        ends[index] = end
        endpoints.update((start, end))

    # 扫描线：一次遍历端点，维护「覆盖当前段」的活跃 claim 集合。
    #
    # 原实现对**每个段**全量扫一遍所有 claim（O(段数 × claim 数)）。在真实
    # 账本上（16 913 条 claim / 18 675 段）这是约 5.7 亿次内层迭代，单次调用
    # 实测 60.50 s —— 覆盖审计的**单线程 CPU 瓶颈**。
    #
    # 等价性：某 claim 覆盖段 [a, b) 当且仅当 claim.start <= a 且 claim.end >= b。
    # 因为 b 是 a 之后的**下一个端点**，而所有 claim 的端点都在 endpoints 里，
    # 所以 claim.end >= b 等价于 claim.end > a。于是「活跃集合」就是
    # {claim : start <= a < end}，可以用起点/终点两个有序指针增量维护。
    # 输出按 claim id 排序（原实现也是按 id 排序），因此与原实现**逐字节一致**；
    # 等价性由 tests/test_audit_rom_byte_coverage_atomize_sweep.py 钉住
    # （真实账本 + 400 组随机输入 + 失败关闭语义 + 性能闸门）。
    by_start = sorted(range(count), key=lambda index: (starts[index], index))
    by_end = sorted(range(count), key=lambda index: (ends[index], index))
    ordered = sorted(endpoints)
    segments: list[dict[str, Any]] = []
    active: set[int] = set()
    add_index = 0
    remove_index = 0
    for start, end in zip(ordered, ordered[1:]):
        while add_index < count and starts[by_start[add_index]] <= start:
            active.add(by_start[add_index])
            add_index += 1
        while remove_index < count and ends[by_end[remove_index]] <= start:
            active.discard(by_end[remove_index])
            remove_index += 1
        active_claims = [normalized[index] for index in sorted(active)]
        primary = sorted(
            (claim for claim in active_claims if claim["role"] == "primary"),
            key=lambda claim: claim["id"],
        )
        secondary = sorted(
            (claim for claim in active_claims if claim["role"] == "secondary"),
            key=lambda claim: claim["id"],
        )
        if len(primary) > 1:
            raise ValueError(
                "conflicting primary claims at "
                f"[0x{start:X}, 0x{end:X}): "
                + ", ".join(claim["id"] for claim in primary)
            )
        if primary:
            segment = {
                "range": [start, end],
                "primary_class": primary[0]["primary_class"],
                "primary_claim_ids": [primary[0]["id"]],
                "secondary_claim_ids": [claim["id"] for claim in secondary],
            }
        else:
            segment = {
                "range": [start, end],
                "primary_class": "unknown",
                "primary_claim_ids": [],
                "secondary_claim_ids": [claim["id"] for claim in secondary],
                "unknown_reason": UNKNOWN_REASON,
            }
        segments.append(segment)
    return segments


def _merge_record_ranges(entries: object, entry_size: object) -> list[tuple[int, int, int]]:
    if not isinstance(entries, list) or not isinstance(entry_size, int) or entry_size <= 0:
        return []
    record_ranges = []
    for entry in entries:
        offset = entry.get("_raw_offset") if isinstance(entry, dict) else None
        if isinstance(offset, int):
            record_ranges.append((offset, offset + entry_size))
    record_ranges.sort()
    merged: list[list[int]] = []
    for start, end in record_ranges:
        if merged and start <= merged[-1][1]:
            merged[-1][1] = max(end, merged[-1][1])
            merged[-1][2] += 1
        else:
            merged.append([start, end, 1])
    return [(start, end, count) for start, end, count in merged]


def _bank_claims(root: Path, rom: bytes) -> list[dict[str, Any]]:
    claims: list[dict[str, Any]] = []
    for path in sorted((root / "sequel/content").glob("*/bank.json")):
        raw = path.read_bytes()
        bank = json.loads(raw)
        slug = path.parent.name
        ranges = _merge_record_ranges(bank.get("entries"), bank.get("entry_size"))
        for index, (start, end, records) in enumerate(ranges):
            if end > len(rom):
                raise ValueError(f"bank {slug} range exceeds the ROM")
            claims.append(
                {
                    "id": f"bank-{slug}-{index:03d}",
                    "range": [start, end],
                    "role": "primary",
                    "primary_class": "fixed_table",
                    "claim_kind": "bank_record_bytes",
                    "bank": slug,
                    "records": records,
                    "bytes_sha256": _sha256(rom[start:end]),
                    "evidence_path": path.relative_to(root).as_posix(),
                    "evidence_sha256": _sha256(raw),
                }
            )
    return claims


def _lz77_claims(root: Path, rom: bytes) -> list[dict[str, Any]]:
    references = _aligned_rom_pointer_references(rom)
    offsets = sorted(
        offset
        for offset in _strict_lz77_offsets(rom)
        if offset % 4 == 0 and offset in references
    )
    if len(offsets) != 896:
        raise ValueError(
            f"aligned pointer-reachable LZ77 denominator changed: {len(offsets)}"
        )
    evidence = root / LZ77_EVIDENCE
    evidence_sha256 = _sha256_file(evidence)
    claims = []
    for offset in offsets:
        parsed = _parse_lz77(rom, offset, materialize=False)
        if parsed is None:
            raise ValueError(f"LZ77 record disappeared at 0x{offset:X}")
        end, _ = parsed
        claims.append(
            {
                "id": f"lz77-{offset:06x}",
                "range": [offset, end],
                "role": "primary",
                "primary_class": "lz77_resource",
                "claim_kind": "aligned_pointer_reachable_lz77",
                "aligned_pointer_reference_count": len(references[offset]),
                "bytes_sha256": _sha256(rom[offset:end]),
                "evidence_path": LZ77_EVIDENCE.as_posix(),
                "evidence_sha256": evidence_sha256,
            }
        )
    return claims


def _unbound_lz77_claims(root: Path, rom: bytes) -> list[dict[str, Any]]:
    root = Path(root).resolve(strict=True)
    artifact_dir = (root / UNBOUND_LZ77_ARTIFACT).absolute()
    try:
        resolved_artifact_dir = artifact_dir.resolve(strict=True)
        resolved_artifact_dir.relative_to(root)
    except (OSError, ValueError) as error:
        raise ValueError("unbound LZ77 artifact is missing or outside the repository") from error
    if resolved_artifact_dir != artifact_dir or not artifact_dir.is_dir():
        raise ValueError("unbound LZ77 artifact uses a symlink or is not a directory")

    artifact_paths = list(artifact_dir.iterdir())
    if {path.name for path in artifact_paths} != {
        "inventory.json",
        "manifest.json",
        "payloads.bin",
        "streams.lz77.bin",
    }:
        raise ValueError("unbound LZ77 artifact file set changed")
    if any(path.is_symlink() or not path.is_file() for path in artifact_paths):
        raise ValueError("unbound LZ77 artifact contains a symlink or non-file entry")

    verifier_path = (root / UNBOUND_LZ77_VERIFIER).absolute()
    try:
        resolved_verifier = verifier_path.resolve(strict=True)
        resolved_verifier.relative_to(root)
    except (OSError, ValueError) as error:
        raise ValueError("unbound LZ77 verifier is missing") from error
    if resolved_verifier != verifier_path or not verifier_path.is_file():
        raise ValueError("unbound LZ77 verifier uses a symlink or is not a file")
    if _sha256_file(verifier_path) != UNBOUND_LZ77_VERIFIER_SHA256:
        raise ValueError("unbound LZ77 verifier SHA-256 changed")

    manifest_path = artifact_dir / "manifest.json"
    manifest_raw = manifest_path.read_bytes()
    if _sha256(manifest_raw) != UNBOUND_LZ77_MANIFEST_SHA256:
        raise ValueError("unbound LZ77 promotion manifest SHA-256 changed")
    manifest = json.loads(manifest_raw)
    expected_files = {
        "inventory.json": UNBOUND_LZ77_PAYLOAD_SHA256,
        "payloads.bin": (
            "7027b4c7ca61cf2b5f92dd3851cefe24bf5b244c7354756504432901055cdd65"
        ),
        "streams.lz77.bin": (
            "2db24f2804ad3d6c11d2cee7cde9a0205e86ae06eab4a02339c7ade130e41505"
        ),
    }
    if (
        manifest.get("schema") != "git-artifact-promotion-v1"
        or manifest.get("artifact_id") != "rom-unbound-lz77-inventory-v1"
        or manifest.get("artifact_schema") != "rom-unbound-lz77-inventory-v1"
        or manifest.get("artifact_status") != "accepted"
        or manifest.get("payload_schema") != "rom-unbound-lz77-inventory-v1"
        or manifest.get("payload_file") != "inventory.json"
        or manifest.get("files") != expected_files
        or manifest.get("scope") != UNBOUND_LZ77_EXPECTED_SCOPE
    ):
        raise ValueError("unbound LZ77 promotion contract changed")
    verifier_record = manifest.get("verifier")
    expected_report = {
        "schema": "rom-unbound-lz77-inventory-verification-v1",
        "verified": True,
        **UNBOUND_LZ77_EXPECTED_SUMMARY,
        "errors": [],
    }
    if (
        not isinstance(verifier_record, dict)
        or verifier_record.get("exit_code") != 0
        or verifier_record.get("verifier_sha256")
        != UNBOUND_LZ77_VERIFIER_SHA256
        or verifier_record.get("report") != expected_report
    ):
        raise ValueError("unbound LZ77 recorded verification contract changed")

    payload_path = artifact_dir / "inventory.json"
    payload_raw = payload_path.read_bytes()
    if _sha256(payload_raw) != UNBOUND_LZ77_PAYLOAD_SHA256:
        raise ValueError("unbound LZ77 inventory payload SHA-256 changed")
    payload = json.loads(payload_raw)
    if (
        payload.get("schema") != "rom-unbound-lz77-inventory-v1"
        or payload.get("rom")
        != {
            "path": ROM_PATH.as_posix(),
            "size": len(rom),
            "sha256": ROM_SHA256,
        }
        or payload.get("summary") != UNBOUND_LZ77_EXPECTED_SUMMARY
        or payload.get("scope") != UNBOUND_LZ77_EXPECTED_SCOPE
        or payload.get("coverage")
        != {
            "path": "sequel/rom-byte-coverage.json",
            "allowed_primary_classes": ["lz77_syntax_unbound", "unknown"],
            "hash_pinned": False,
            "hash_pin_omission_reason": (
                "coverage incorporates these claims, so a coverage hash would "
                "create a dependency cycle; the verifier reconstructs its "
                "gap-free state and allowed classes instead"
            ),
        }
    ):
        raise ValueError("unbound LZ77 inventory contract changed")

    report = verify_rom_unbound_lz77_inventory(root, artifact_dir)
    if report != expected_report:
        raise ValueError(f"unbound LZ77 independent verification failed: {report}")

    records = payload.get("records")
    if not isinstance(records, list) or len(records) != 41:
        raise ValueError("unbound LZ77 record denominator changed")
    claims: list[dict[str, Any]] = []
    previous_end = -1
    compressed_cursor = 0
    decompressed_cursor = 0
    for index, record in enumerate(records):
        if not isinstance(record, dict):
            raise ValueError("unbound LZ77 record is not an object")
        value = record.get("range")
        if (
            not isinstance(value, list)
            or len(value) != 2
            or not all(isinstance(item, int) for item in value)
        ):
            raise ValueError("unbound LZ77 record range is invalid")
        start, end = value
        if start < previous_end or start < 0 or start >= end or end > len(rom):
            raise ValueError("unbound LZ77 record ranges overlap or leave the ROM")
        if (
            record.get("classification") != "lz77_syntax_unbound"
            or record.get("aligned_pointer_reference_count") != 0
            or record.get("runtime_reachability_claimed") is not False
            or record.get("compressed_size") != end - start
            or record.get("compressed_bundle_offset") != compressed_cursor
            or record.get("decompressed_bundle_offset") != decompressed_cursor
        ):
            raise ValueError("unbound LZ77 record contract changed")
        compressed_sha256 = record.get("compressed_sha256")
        if compressed_sha256 != _sha256(rom[start:end]):
            raise ValueError(f"unbound LZ77 ROM bytes changed at 0x{start:06X}")
        decompressed_size = record.get("decompressed_size")
        if not isinstance(decompressed_size, int) or decompressed_size <= 0:
            raise ValueError("unbound LZ77 decompressed size is invalid")
        claims.append(
            {
                "id": f"unbound-lz77-{index:02d}-{start:06x}",
                "range": [start, end],
                "role": "primary",
                "primary_class": "lz77_syntax_unbound",
                "claim_kind": "unbound_strict_lz77_syntax_range",
                "record_index": index,
                "aligned_pointer_reference_count": 0,
                "runtime_reachability_claimed": False,
                "bytes_sha256": compressed_sha256,
                "evidence_path": (
                    UNBOUND_LZ77_ARTIFACT / "inventory.json"
                ).as_posix(),
                "evidence_sha256": UNBOUND_LZ77_PAYLOAD_SHA256,
                "evidence_selector": f"/records/{index}",
                "promotion_manifest_path": (
                    UNBOUND_LZ77_ARTIFACT / "manifest.json"
                ).as_posix(),
                "promotion_manifest_sha256": UNBOUND_LZ77_MANIFEST_SHA256,
                "independent_verifier_path": UNBOUND_LZ77_VERIFIER.as_posix(),
                "independent_verifier_sha256": UNBOUND_LZ77_VERIFIER_SHA256,
                "limitations": [
                    "Strict type-0x10 syntax is proven, but consumer identity, runtime reachability, resource role, and graphics semantics are not claimed."
                ],
            }
        )
        previous_end = end
        compressed_cursor += end - start
        decompressed_cursor += decompressed_size
    if (
        compressed_cursor
        != UNBOUND_LZ77_EXPECTED_SUMMARY["selected_compressed_bytes"]
        or decompressed_cursor
        != UNBOUND_LZ77_EXPECTED_SUMMARY["selected_decompressed_bytes"]
    ):
        raise ValueError("unbound LZ77 selected byte denominator changed")
    return claims


def _cfg_inventory_claims(
    root: Path,
    rom: bytes,
    existing_claims: Iterable[dict[str, Any]],
) -> list[dict[str, Any]]:
    """Promote only baseline-unknown bytes reached by the fixed-root CFG."""

    root = Path(root).resolve(strict=True)
    baseline_claims = list(existing_claims)
    if any(
        claim.get("claim_kind") == "cfg_reachable_instruction_bytes"
        for claim in baseline_claims
    ):
        raise ValueError("CFG inventory claims must be derived from a pre-CFG baseline")

    artifact_dir = (root / CFG_INVENTORY_ARTIFACT).absolute()
    try:
        resolved_artifact = artifact_dir.resolve(strict=True)
        resolved_artifact.relative_to(root)
    except (OSError, ValueError) as error:
        raise ValueError("CFG inventory artifact is missing or outside the repository") from error
    if resolved_artifact != artifact_dir or not artifact_dir.is_dir():
        raise ValueError("CFG inventory artifact uses a symlink or is not a directory")
    members = list(artifact_dir.iterdir())
    if (
        {member.name for member in members}
        != {"manifest.json", "rom-cfg-inventory.json"}
        or any(member.is_symlink() or not member.is_file() for member in members)
    ):
        raise ValueError("CFG inventory artifact file set changed")

    verifier_path = (root / CFG_INVENTORY_VERIFIER).absolute()
    try:
        resolved_verifier = verifier_path.resolve(strict=True)
        resolved_verifier.relative_to(root)
    except (OSError, ValueError) as error:
        raise ValueError("CFG inventory verifier is missing") from error
    if resolved_verifier != verifier_path or not verifier_path.is_file():
        raise ValueError("CFG inventory verifier uses a symlink or is not a file")
    if _sha256_file(verifier_path) != CFG_INVENTORY_VERIFIER_SHA256:
        raise ValueError("CFG inventory verifier SHA-256 changed")

    manifest_path = artifact_dir / "manifest.json"
    payload_path = artifact_dir / "rom-cfg-inventory.json"
    manifest_raw = manifest_path.read_bytes()
    payload_raw = payload_path.read_bytes()
    if _sha256(manifest_raw) != CFG_INVENTORY_MANIFEST_SHA256:
        raise ValueError("CFG inventory manifest SHA-256 changed")
    if _sha256(payload_raw) != CFG_INVENTORY_PAYLOAD_SHA256:
        raise ValueError("CFG inventory payload SHA-256 changed")
    manifest = json.loads(manifest_raw)
    payload = json.loads(payload_raw)
    expected_rom = {
        "path": ROM_PATH.as_posix(),
        "size": len(rom),
        "sha256": ROM_SHA256,
    }
    if (
        manifest.get("artifact_schema") != "rom-cfg-inventory-v2"
        or manifest.get("rom") != expected_rom
        or manifest.get("summary") != CFG_INVENTORY_EXPECTED_SUMMARY
        or manifest.get("scope") != CFG_INVENTORY_EXPECTED_SCOPE
        or manifest.get("graph_denominator_sha256")
        != CFG_INVENTORY_GRAPH_SHA256
        or manifest.get("files")
        != {
            "rom-cfg-inventory.json": {
                "size": len(payload_raw),
                "sha256": CFG_INVENTORY_PAYLOAD_SHA256,
            }
        }
        or manifest.get("implementation", {}).get("verifier_sha256")
        != CFG_INVENTORY_VERIFIER_SHA256
    ):
        raise ValueError("CFG inventory promotion contract changed")
    if (
        payload.get("schema") != "rom-cfg-inventory-v2"
        or payload.get("rom") != expected_rom
        or payload.get("summary") != CFG_INVENTORY_EXPECTED_SUMMARY
        or payload.get("scope") != CFG_INVENTORY_EXPECTED_SCOPE
        or payload.get("graph_denominator_sha256")
        != CFG_INVENTORY_GRAPH_SHA256
    ):
        raise ValueError("CFG inventory payload contract changed")

    report = verify_rom_cfg_inventory(root, artifact_dir)
    if report != CFG_INVENTORY_EXPECTED_REPORT:
        raise ValueError(f"CFG inventory independent verification failed: {report}")

    baseline_segments = atomize_claims(len(rom), baseline_claims)
    unknown_ranges = [
        tuple(segment["range"])
        for segment in baseline_segments
        if segment["primary_class"] == "unknown"
    ]
    blocks = payload.get("blocks")
    if not isinstance(blocks, list) or len(blocks) != 7_725:
        raise ValueError("CFG inventory block denominator changed")

    source_pieces: list[dict[str, Any]] = []
    unknown_index = 0
    previous_block_end = -1
    for block in blocks:
        if not isinstance(block, dict):
            raise ValueError("CFG inventory block is not an object")
        mode = block.get("mode")
        value = block.get("range")
        if (
            mode not in {"arm", "thumb"}
            or not isinstance(value, list)
            or len(value) != 2
            or not all(isinstance(item, int) for item in value)
        ):
            raise ValueError("CFG inventory block schema changed")
        start, end = value
        block_id = block.get("id")
        if (
            block_id != f"block-{mode}-{start:06x}"
            or start < previous_block_end
            or start < 0
            or start >= end
            or end > len(rom)
            or block.get("bytes_sha256") != _sha256(rom[start:end])
            or not isinstance(block.get("instruction_count"), int)
            or block["instruction_count"] <= 0
        ):
            raise ValueError(f"CFG inventory block bytes or identity changed: {block_id}")
        previous_block_end = end
        while (
            unknown_index < len(unknown_ranges)
            and unknown_ranges[unknown_index][1] <= start
        ):
            unknown_index += 1
        scan_index = unknown_index
        while (
            scan_index < len(unknown_ranges)
            and unknown_ranges[scan_index][0] < end
        ):
            unknown_start, unknown_end = unknown_ranges[scan_index]
            piece_start = max(start, unknown_start)
            piece_end = min(end, unknown_end)
            if piece_start < piece_end:
                source_pieces.append(
                    {
                        "mode": mode,
                        "block_id": block_id,
                        "range": [piece_start, piece_end],
                    }
                )
            scan_index += 1

    if len(source_pieces) != CFG_PROMOTED_SOURCE_PIECES:
        raise ValueError(
            "CFG inventory unknown-intersection denominator changed: "
            f"{len(source_pieces)}"
        )
    merged: list[dict[str, Any]] = []
    for piece in source_pieces:
        start, end = piece["range"]
        if (
            merged
            and merged[-1]["mode"] == piece["mode"]
            and merged[-1]["range"][1] == start
        ):
            merged[-1]["range"][1] = end
            merged[-1]["source_blocks"].append(
                {"block_id": piece["block_id"], "range": piece["range"]}
            )
        else:
            if merged and start < merged[-1]["range"][1]:
                raise ValueError("CFG inventory promoted ranges overlap")
            merged.append(
                {
                    "mode": piece["mode"],
                    "range": [start, end],
                    "source_blocks": [
                        {"block_id": piece["block_id"], "range": piece["range"]}
                    ],
                }
            )
    promoted_bytes = sum(end - start for start, end in (item["range"] for item in merged))
    if (
        len(merged) != CFG_PROMOTED_CLAIM_COUNT
        or promoted_bytes != CFG_PROMOTED_UNKNOWN_BYTES
        or any(item["mode"] != "thumb" for item in merged)
    ):
        raise ValueError(
            "CFG inventory promoted claim denominator changed: "
            f"claims={len(merged)}, bytes={promoted_bytes}"
        )

    claims: list[dict[str, Any]] = []
    for index, item in enumerate(merged):
        start, end = item["range"]
        mode = item["mode"]
        source_blocks = item["source_blocks"]
        claims.append(
            {
                "id": f"cfg-{mode}-{index:04d}-{start:06x}",
                "range": [start, end],
                "role": "primary",
                "primary_class": f"armv4t_cfg_reachable_{mode}_code",
                "claim_kind": "cfg_reachable_instruction_bytes",
                "mode": mode,
                "source_block_count": len(source_blocks),
                "source_blocks": source_blocks,
                "fixed_root_count": 263,
                "graph_denominator_sha256": CFG_INVENTORY_GRAPH_SHA256,
                "promoted_from_primary_class": "unknown",
                "runtime_reachability_claimed": False,
                "global_code_map_claimed": False,
                "bytes_sha256": _sha256(rom[start:end]),
                "evidence_path": (
                    CFG_INVENTORY_ARTIFACT / "rom-cfg-inventory.json"
                ).as_posix(),
                "evidence_sha256": CFG_INVENTORY_PAYLOAD_SHA256,
                "evidence_selector": "/blocks",
                "promotion_manifest_path": (
                    CFG_INVENTORY_ARTIFACT / "manifest.json"
                ).as_posix(),
                "promotion_manifest_sha256": CFG_INVENTORY_MANIFEST_SHA256,
                "independent_verifier_path": CFG_INVENTORY_VERIFIER.as_posix(),
                "independent_verifier_sha256": CFG_INVENTORY_VERIFIER_SHA256,
                "limitations": [
                    "Only bytes reached from the fixed 263-root denominator and still unknown in the pre-CFG coverage baseline are promoted.",
                    "Indirect targets, global function discovery, and natural runtime reachability remain unproven.",
                ],
            }
        )
    return claims


def _cfg_inventory_v3_claims(
    root: Path,
    rom: bytes,
    existing_claims: Iterable[dict[str, Any]],
) -> list[dict[str, Any]]:
    """Promote only current unknown bytes proven by the one-generation v3 delta."""

    root = Path(root).resolve(strict=True)
    baseline_claims = list(existing_claims)
    v3_kinds = {
        "cfg_v3_reachable_instruction_bytes",
        "cfg_v3_indexed_dispatch_table_cell",
        "cfg_v3_sparse_dispatch_masked_residual_cell",
    }
    if any(claim.get("claim_kind") in v3_kinds for claim in baseline_claims):
        raise ValueError("CFG v3 claims must be derived from a pre-v3 baseline")

    artifact_dir = (root / CFG_V3_INVENTORY_ARTIFACT).absolute()
    try:
        resolved_artifact = artifact_dir.resolve(strict=True)
        resolved_artifact.relative_to(root)
    except (OSError, ValueError) as error:
        raise ValueError("CFG v3 artifact is missing or outside the repository") from error
    if resolved_artifact != artifact_dir or not artifact_dir.is_dir():
        raise ValueError("CFG v3 artifact uses a symlink or is not a directory")
    members = list(artifact_dir.iterdir())
    if (
        {member.name for member in members}
        != {"manifest.json", "rom-cfg-inventory-v3.json"}
        or any(member.is_symlink() or not member.is_file() for member in members)
    ):
        raise ValueError("CFG v3 artifact file set changed")

    verifier_path = (root / CFG_V3_INVENTORY_VERIFIER).absolute()
    try:
        resolved_verifier = verifier_path.resolve(strict=True)
        resolved_verifier.relative_to(root)
    except (OSError, ValueError) as error:
        raise ValueError("CFG v3 verifier is missing") from error
    if resolved_verifier != verifier_path or not verifier_path.is_file():
        raise ValueError("CFG v3 verifier uses a symlink or is not a file")
    if _sha256_file(verifier_path) != CFG_V3_INVENTORY_VERIFIER_SHA256:
        raise ValueError("CFG v3 verifier SHA-256 changed")

    manifest_path = artifact_dir / "manifest.json"
    payload_path = artifact_dir / "rom-cfg-inventory-v3.json"
    manifest_raw = manifest_path.read_bytes()
    payload_raw = payload_path.read_bytes()
    if _sha256(manifest_raw) != CFG_V3_INVENTORY_MANIFEST_SHA256:
        raise ValueError("CFG v3 manifest SHA-256 changed")
    if _sha256(payload_raw) != CFG_V3_INVENTORY_PAYLOAD_SHA256:
        raise ValueError("CFG v3 payload SHA-256 changed")
    manifest = json.loads(manifest_raw)
    payload = json.loads(payload_raw)
    expected_rom = {
        "path": ROM_PATH.as_posix(),
        "size": len(rom),
        "sha256": ROM_SHA256,
    }
    expected_dispatch_summary = {
        "baseline_indirect_frontier_count": 357,
        "resolved_frontier_count": 29,
        "unresolved_baseline_indirect_frontier_count": 328,
        "ordered_edge_count": 677,
        "unique_target_count": 290,
        "ordered_target_vector_sha256": (
            "ab4572dcb948a49e6172e18f2fd9c482e61ee018c42cf0be77bd0e67f0c86615"
        ),
    }
    if (
        manifest.get("artifact_schema") != "rom-cfg-inventory-v3"
        or manifest.get("rom") != expected_rom
        or manifest.get("base_cfg", {}).get("graph_denominator_sha256")
        != CFG_INVENTORY_GRAPH_SHA256
        or manifest.get("static_dispatch_summary") != expected_dispatch_summary
        or manifest.get("extension_policy") != CFG_V3_EXPECTED_POLICY
        or manifest.get("extension_summary")
        != CFG_V3_EXPECTED_EXTENSION_SUMMARY
        or manifest.get("combined_summary") != CFG_V3_EXPECTED_COMBINED_SUMMARY
        or manifest.get("graph_denominator_sha256")
        != CFG_V3_INVENTORY_GRAPH_SHA256
        or manifest.get("scope") != CFG_V3_EXPECTED_SCOPE
        or manifest.get("files")
        != {
            "rom-cfg-inventory-v3.json": {
                "size": len(payload_raw),
                "sha256": CFG_V3_INVENTORY_PAYLOAD_SHA256,
            }
        }
        or manifest.get("implementation", {}).get("verifier_sha256")
        != CFG_V3_INVENTORY_VERIFIER_SHA256
    ):
        raise ValueError("CFG v3 promotion manifest contract changed")
    static_dispatches = payload.get("static_dispatches")
    extension = payload.get("extension")
    if (
        payload.get("schema") != "rom-cfg-inventory-v3"
        or payload.get("rom") != expected_rom
        or payload.get("base_cfg") != manifest.get("base_cfg")
        or payload.get("extension_policy") != CFG_V3_EXPECTED_POLICY
        or not isinstance(static_dispatches, dict)
        or {
            key: static_dispatches.get(key) for key in expected_dispatch_summary
        }
        != expected_dispatch_summary
        or not isinstance(extension, dict)
        or extension.get("summary") != CFG_V3_EXPECTED_EXTENSION_SUMMARY
        or payload.get("combined_summary") != CFG_V3_EXPECTED_COMBINED_SUMMARY
        or payload.get("graph_denominator_sha256")
        != CFG_V3_INVENTORY_GRAPH_SHA256
        or payload.get("scope") != CFG_V3_EXPECTED_SCOPE
    ):
        raise ValueError("CFG v3 payload contract changed")
    report = verify_rom_cfg_inventory_v3(root, artifact_dir)
    if report != CFG_V3_EXPECTED_REPORT:
        raise ValueError(f"CFG v3 independent verification failed: {report}")

    baseline_segments = atomize_claims(len(rom), baseline_claims)
    unknown_ranges = [
        tuple(segment["range"])
        for segment in baseline_segments
        if segment["primary_class"] == "unknown"
    ]

    blocks = extension.get("blocks")
    if not isinstance(blocks, list) or len(blocks) != 891:
        raise ValueError("CFG v3 extension block denominator changed")
    source_pieces: list[dict[str, Any]] = []
    unknown_index = 0
    previous_end = -1
    for block in blocks:
        if not isinstance(block, dict):
            raise ValueError("CFG v3 extension block is not an object")
        mode = block.get("mode")
        value = block.get("range")
        if (
            mode != "thumb"
            or not isinstance(value, list)
            or len(value) != 2
            or not all(isinstance(item, int) for item in value)
        ):
            raise ValueError("CFG v3 extension block schema changed")
        start, end = value
        block_id = block.get("id")
        if (
            block_id != f"block-{mode}-{start:06x}"
            or start < previous_end
            or start < 0
            or start >= end
            or end > len(rom)
            or block.get("bytes_sha256") != _sha256(rom[start:end])
            or not isinstance(block.get("instruction_count"), int)
            or block["instruction_count"] <= 0
        ):
            raise ValueError(
                f"CFG v3 extension block bytes or identity changed: {block_id}"
            )
        previous_end = end
        while (
            unknown_index < len(unknown_ranges)
            and unknown_ranges[unknown_index][1] <= start
        ):
            unknown_index += 1
        scan_index = unknown_index
        while scan_index < len(unknown_ranges) and unknown_ranges[scan_index][0] < end:
            unknown_start, unknown_end = unknown_ranges[scan_index]
            piece_start = max(start, unknown_start)
            piece_end = min(end, unknown_end)
            if piece_start < piece_end:
                source_pieces.append(
                    {
                        "mode": mode,
                        "block_id": block_id,
                        "range": [piece_start, piece_end],
                    }
                )
            scan_index += 1

    merged: list[dict[str, Any]] = []
    for piece in source_pieces:
        start, end = piece["range"]
        if merged and merged[-1]["range"][1] == start:
            merged[-1]["range"][1] = end
            merged[-1]["source_blocks"].append(
                {"block_id": piece["block_id"], "range": piece["range"]}
            )
        else:
            if merged and start < merged[-1]["range"][1]:
                raise ValueError("CFG v3 promoted code ranges overlap")
            merged.append(
                {
                    "mode": piece["mode"],
                    "range": [start, end],
                    "source_blocks": [
                        {"block_id": piece["block_id"], "range": piece["range"]}
                    ],
                }
            )
    promoted_code_bytes = sum(
        item["range"][1] - item["range"][0] for item in merged
    )
    if (
        len(source_pieces) != CFG_V3_PROMOTED_SOURCE_PIECES
        or len(merged) != CFG_V3_PROMOTED_CODE_CLAIM_COUNT
        or promoted_code_bytes != CFG_V3_PROMOTED_CODE_BYTES
    ):
        raise ValueError(
            "CFG v3 promoted code denominator changed: "
            f"pieces={len(source_pieces)}, claims={len(merged)}, "
            f"bytes={promoted_code_bytes}"
        )

    code_claims = []
    for index, item in enumerate(merged):
        start, end = item["range"]
        code_claims.append(
            {
                "id": f"cfg-v3-thumb-{index:04d}-{start:06x}",
                "range": [start, end],
                "role": "primary",
                "primary_class": "armv4t_cfg_v3_reachable_thumb_code",
                "claim_kind": "cfg_v3_reachable_instruction_bytes",
                "mode": "thumb",
                "source_block_count": len(item["source_blocks"]),
                "source_blocks": item["source_blocks"],
                "base_graph_denominator_sha256": CFG_INVENTORY_GRAPH_SHA256,
                "extension_graph_denominator_sha256": CFG_V3_INVENTORY_GRAPH_SHA256,
                "resolver_generation_count": 1,
                "promoted_from_primary_class": "unknown",
                "runtime_reachability_claimed": False,
                "global_code_map_claimed": False,
                "bytes_sha256": _sha256(rom[start:end]),
                "evidence_path": (
                    CFG_V3_INVENTORY_ARTIFACT / "rom-cfg-inventory-v3.json"
                ).as_posix(),
                "evidence_sha256": CFG_V3_INVENTORY_PAYLOAD_SHA256,
                "evidence_selector": "/extension/blocks",
                "promotion_manifest_path": (
                    CFG_V3_INVENTORY_ARTIFACT / "manifest.json"
                ).as_posix(),
                "promotion_manifest_sha256": CFG_V3_INVENTORY_MANIFEST_SHA256,
                "independent_verifier_path": CFG_V3_INVENTORY_VERIFIER.as_posix(),
                "independent_verifier_sha256": CFG_V3_INVENTORY_VERIFIER_SHA256,
                "promotion_batch": "cfg-v3-one-generation",
                "limitations": [
                    "Only bytes in the 101-entry one-generation direct CFG extension that remain unknown after all prior claims are promoted.",
                    "The 15 new indirect frontiers remain unresolved and runtime reachability is not claimed.",
                ],
            }
        )

    dispatches = static_dispatches.get("dispatches")
    if not isinstance(dispatches, list) or len(dispatches) != 29:
        raise ValueError("CFG v3 dispatch denominator changed")
    cell_records = []
    for dispatch_index, dispatch in enumerate(dispatches):
        targets = dispatch.get("targets") if isinstance(dispatch, dict) else None
        if not isinstance(targets, list):
            raise ValueError("CFG v3 dispatch target list changed")
        for target_index, target in enumerate(targets):
            if not isinstance(target, dict):
                raise ValueError("CFG v3 dispatch target is not an object")
            start = target.get("entry_offset")
            pointer = target.get("raw_pointer")
            if (
                not isinstance(start, int)
                or not isinstance(pointer, int)
                or start < 0
                or start + 4 > len(rom)
                or int.from_bytes(rom[start : start + 4], "little") != pointer
            ):
                raise ValueError("CFG v3 dispatch table cell bytes changed")
            cell_records.append(
                {
                    "range": [start, start + 4],
                    "dispatch_index": dispatch_index,
                    "target_index": target_index,
                    "source_frontier_id": dispatch["source_frontier_id"],
                    "slot_index": target["slot_index"],
                    "raw_pointer": pointer,
                }
            )
    cell_records.sort(key=lambda item: item["range"])
    if (
        len(cell_records) != 677
        or len({tuple(item["range"]) for item in cell_records}) != 677
        or any(
            first["range"][1] > second["range"][0]
            for first, second in zip(cell_records, cell_records[1:])
        )
    ):
        raise ValueError("CFG v3 physical dispatch cell denominator changed")

    table_claims = []
    unknown_index = 0
    partial_unknown_cells = []
    for cell in cell_records:
        start, end = cell["range"]
        while (
            unknown_index < len(unknown_ranges)
            and unknown_ranges[unknown_index][1] <= start
        ):
            unknown_index += 1
        unknown_bytes = 0
        scan_index = unknown_index
        while scan_index < len(unknown_ranges) and unknown_ranges[scan_index][0] < end:
            unknown_start, unknown_end = unknown_ranges[scan_index]
            unknown_bytes += max(
                0, min(end, unknown_end) - max(start, unknown_start)
            )
            scan_index += 1
        if unknown_bytes == 0:
            continue
        if unknown_bytes != 4:
            partial_unknown_cells.append((start, unknown_bytes))
            continue
        table_claims.append(
            {
                "id": f"cfg-v3-dispatch-cell-{start:06x}",
                "range": [start, end],
                "role": "primary",
                "primary_class": "thumb_indexed_dispatch_table_cell",
                "claim_kind": "cfg_v3_indexed_dispatch_table_cell",
                "source_frontier_id": cell["source_frontier_id"],
                "slot_index": cell["slot_index"],
                "raw_pointer": cell["raw_pointer"],
                "promoted_from_primary_class": "unknown",
                "runtime_reachability_claimed": False,
                "bytes_sha256": _sha256(rom[start:end]),
                "evidence_path": (
                    CFG_V3_INVENTORY_ARTIFACT / "rom-cfg-inventory-v3.json"
                ).as_posix(),
                "evidence_sha256": CFG_V3_INVENTORY_PAYLOAD_SHA256,
                "evidence_selector": (
                    f"/static_dispatches/dispatches/{cell['dispatch_index']}"
                    f"/targets/{cell['target_index']}"
                ),
                "promotion_manifest_path": (
                    CFG_V3_INVENTORY_ARTIFACT / "manifest.json"
                ).as_posix(),
                "promotion_manifest_sha256": CFG_V3_INVENTORY_MANIFEST_SHA256,
                "independent_verifier_path": CFG_V3_INVENTORY_VERIFIER.as_posix(),
                "independent_verifier_sha256": CFG_V3_INVENTORY_VERIFIER_SHA256,
                "promotion_batch": "cfg-v3-one-generation",
                "limitations": [
                    "This claim proves a reachable indexed-dispatch pointer cell, not the semantic purpose of its target routine."
                ],
            }
        )
    if partial_unknown_cells:
        raise ValueError(
            f"CFG v3 dispatch cells are only partially unknown: {partial_unknown_cells[:8]}"
        )
    promoted_table_bytes = sum(
        claim["range"][1] - claim["range"][0] for claim in table_claims
    )
    if (
        len(table_claims) != CFG_V3_PROMOTED_TABLE_CELL_COUNT
        or promoted_table_bytes != CFG_V3_PROMOTED_TABLE_BYTES
    ):
        raise ValueError(
            "CFG v3 promoted table denominator changed: "
            f"claims={len(table_claims)}, bytes={promoted_table_bytes}"
        )

    sparse_dispatch_contract = {
        9: {
            "source_frontier_id": "frontier-000124",
            "table_range": [0x06EE98, 0x06EEBC],
        },
        19: {
            "source_frontier_id": "frontier-000177",
            "table_range": [0x07BED0, 0x07BEF4],
        },
    }
    residual_records: list[dict[str, Any]] = []
    selected_cell_starts = {cell["range"][0] for cell in cell_records}
    for dispatch_index, expected in sparse_dispatch_contract.items():
        dispatch = dispatches[dispatch_index]
        table_range = dispatch.get("table_range")
        allowed_indices = dispatch.get("allowed_indices")
        if (
            dispatch.get("source_frontier_id")
            != expected["source_frontier_id"]
            or table_range != expected["table_range"]
            or dispatch.get("comparison_max") != 8
            or allowed_indices != [0, 2, 4, 6, 8]
            or dispatch.get("table_sha256")
            != _sha256(rom[slice(*expected["table_range"])])
            or [target.get("slot_index") for target in dispatch.get("targets", [])]
            != allowed_indices
        ):
            raise ValueError("CFG v3 sparse dispatch contract changed")
        table_start, table_end = expected["table_range"]
        if table_end - table_start != 9 * 4:
            raise ValueError("CFG v3 sparse dispatch table size changed")
        for slot_index in range(9):
            start = table_start + slot_index * 4
            if slot_index in allowed_indices:
                if start not in selected_cell_starts:
                    raise ValueError("CFG v3 selected sparse dispatch cell is missing")
                continue
            if start in selected_cell_starts:
                raise ValueError("CFG v3 masked residual cell became selected")
            residual_records.append(
                {
                    "range": [start, start + 4],
                    "dispatch_index": dispatch_index,
                    "source_frontier_id": dispatch["source_frontier_id"],
                    "slot_index": slot_index,
                    "raw_value": int.from_bytes(rom[start : start + 4], "little"),
                }
            )

    residual_claims: list[dict[str, Any]] = []
    partial_residual_cells = []
    for record in residual_records:
        start, end = record["range"]
        unknown_bytes = sum(
            max(0, min(end, unknown_end) - max(start, unknown_start))
            for unknown_start, unknown_end in unknown_ranges
            if unknown_start < end and start < unknown_end
        )
        if unknown_bytes == 0:
            continue
        if unknown_bytes != 4:
            partial_residual_cells.append((start, unknown_bytes))
            continue
        residual_claims.append(
            {
                "id": f"cfg-v3-sparse-residual-cell-{start:06x}",
                "range": [start, end],
                "role": "primary",
                "primary_class": "thumb_sparse_dispatch_masked_residual_cell",
                "claim_kind": "cfg_v3_sparse_dispatch_masked_residual_cell",
                "source_frontier_id": record["source_frontier_id"],
                "slot_index": record["slot_index"],
                "raw_value": record["raw_value"],
                "dispatch_selected": False,
                "runtime_reachability_claimed": False,
                "target_reachability_claimed": False,
                "global_code_map_claimed": False,
                "promoted_from_primary_class": "unknown",
                "bytes_sha256": _sha256(rom[start:end]),
                "range_denominator_sha256": (
                    CFG_V3_SPARSE_RESIDUAL_RANGE_DENOMINATOR_SHA256
                ),
                "evidence_path": (
                    CFG_V3_INVENTORY_ARTIFACT / "rom-cfg-inventory-v3.json"
                ).as_posix(),
                "evidence_sha256": CFG_V3_INVENTORY_PAYLOAD_SHA256,
                "evidence_selector": (
                    f"/static_dispatches/dispatches/{record['dispatch_index']}"
                    "/table_range"
                ),
                "promotion_manifest_path": (
                    CFG_V3_INVENTORY_ARTIFACT / "manifest.json"
                ).as_posix(),
                "promotion_manifest_sha256": CFG_V3_INVENTORY_MANIFEST_SHA256,
                "independent_verifier_path": CFG_V3_INVENTORY_VERIFIER.as_posix(),
                "independent_verifier_sha256": CFG_V3_INVENTORY_VERIFIER_SHA256,
                "promotion_batch": "cfg-v3-one-generation",
                "limitations": [
                    "This is a physical cell inside a frozen sparse dispatch table but the proven mask never selects this slot.",
                    "Runtime or target reachability, code semantics, and a global code map are not claimed.",
                ],
            }
        )
    if partial_residual_cells:
        raise ValueError(
            "CFG v3 sparse residual cells are only partially unknown: "
            f"{partial_residual_cells[:8]}"
        )
    residual_range_denominator = _sha256(
        json.dumps(
            [claim["range"] for claim in residual_claims],
            separators=(",", ":"),
        ).encode("ascii")
    )
    residual_bytes = sum(
        claim["range"][1] - claim["range"][0] for claim in residual_claims
    )
    if (
        len(residual_claims) != CFG_V3_SPARSE_RESIDUAL_CELL_COUNT
        or residual_bytes != CFG_V3_SPARSE_RESIDUAL_BYTES
        or residual_range_denominator
        != CFG_V3_SPARSE_RESIDUAL_RANGE_DENOMINATOR_SHA256
    ):
        raise ValueError(
            "CFG v3 sparse residual denominator changed: "
            f"claims={len(residual_claims)}, bytes={residual_bytes}, "
            f"sha256={residual_range_denominator}"
        )
    for code_claim in code_claims:
        code_start, code_end = code_claim["range"]
        if any(
            code_start < table_claim["range"][1]
            and table_claim["range"][0] < code_end
            for table_claim in [*table_claims, *residual_claims]
        ):
            raise ValueError("CFG v3 promoted code overlaps promoted table cells")
    return code_claims + table_claims + residual_claims


def _cfg_proven_roots_claims(
    root: Path,
    rom: bytes,
    existing_claims: Iterable[dict[str, Any]],
) -> list[dict[str, Any]]:
    """Promote unknown bytes proven by two direct-call CFG roots and producers."""

    root = Path(root).resolve(strict=True)
    baseline_claims = list(existing_claims)
    kinds = {
        "cfg_proven_roots_reachable_instruction_bytes",
        "cfg_proven_roots_direct_thumb_bl_producer",
    }
    if any(claim.get("claim_kind") in kinds for claim in baseline_claims):
        raise ValueError(
            "CFG proven-root claims must be derived from a pre-proven-root baseline"
        )
    if len(rom) != 6_291_456 or _sha256(rom) != ROM_SHA256:
        raise ValueError("CFG proven-root ROM identity changed")

    artifact_dir = (root / CFG_PROVEN_ROOTS_ARTIFACT).absolute()
    try:
        resolved_artifact = artifact_dir.resolve(strict=True)
        resolved_artifact.relative_to(root)
    except (OSError, ValueError) as error:
        raise ValueError(
            "CFG proven-root artifact is missing or outside the repository"
        ) from error
    if resolved_artifact != artifact_dir or not artifact_dir.is_dir():
        raise ValueError("CFG proven-root artifact uses a symlink or is not a directory")
    members = list(artifact_dir.iterdir())
    if (
        {member.name for member in members}
        != {"manifest.json", "rom-cfg-proven-roots.json"}
        or any(member.is_symlink() or not member.is_file() for member in members)
    ):
        raise ValueError("CFG proven-root artifact file set changed")

    verifier_path = (root / CFG_PROVEN_ROOTS_VERIFIER).absolute()
    try:
        resolved_verifier = verifier_path.resolve(strict=True)
        resolved_verifier.relative_to(root)
    except (OSError, ValueError) as error:
        raise ValueError("CFG proven-root verifier is missing") from error
    if resolved_verifier != verifier_path or not verifier_path.is_file():
        raise ValueError("CFG proven-root verifier uses a symlink or is not a file")
    if _sha256_file(verifier_path) != CFG_PROVEN_ROOTS_VERIFIER_SHA256:
        raise ValueError("CFG proven-root verifier SHA-256 changed")

    manifest_path = artifact_dir / "manifest.json"
    payload_path = artifact_dir / "rom-cfg-proven-roots.json"
    manifest_raw = manifest_path.read_bytes()
    payload_raw = payload_path.read_bytes()
    if _sha256(manifest_raw) != CFG_PROVEN_ROOTS_MANIFEST_SHA256:
        raise ValueError("CFG proven-root manifest SHA-256 changed")
    if (
        len(payload_raw) != CFG_PROVEN_ROOTS_PAYLOAD_SIZE
        or _sha256(payload_raw) != CFG_PROVEN_ROOTS_PAYLOAD_SHA256
    ):
        raise ValueError("CFG proven-root payload identity changed")
    manifest = json.loads(manifest_raw)
    payload = json.loads(payload_raw)
    expected_rom = {
        "path": ROM_PATH.as_posix(),
        "size": len(rom),
        "sha256": ROM_SHA256,
    }
    expected_file = {
        "rom-cfg-proven-roots.json": {
            "size": CFG_PROVEN_ROOTS_PAYLOAD_SIZE,
            "sha256": CFG_PROVEN_ROOTS_PAYLOAD_SHA256,
        }
    }
    if (
        manifest.get("artifact_schema") != "rom-cfg-proven-roots-v1"
        or manifest.get("rom") != expected_rom
        or manifest.get("producer_summary")
        != {
            "count": 3,
            "denominator_sha256": CFG_PROVEN_ROOTS_PRODUCER_SHA256,
        }
        or manifest.get("root_count") != 2
        or manifest.get("root_denominator_sha256")
        != CFG_PROVEN_ROOTS_ROOT_SHA256
        or manifest.get("extension_summary")
        != CFG_PROVEN_ROOTS_EXPECTED_EXTENSION_SUMMARY
        or manifest.get("cross_edge_summary")
        != CFG_PROVEN_ROOTS_EXPECTED_CROSS_SUMMARY
        or manifest.get("graph_denominator_sha256")
        != CFG_PROVEN_ROOTS_GRAPH_SHA256
        or manifest.get("scope") != CFG_PROVEN_ROOTS_EXPECTED_SCOPE
        or manifest.get("files") != expected_file
        or manifest.get("implementation", {}).get("verifier_sha256")
        != CFG_PROVEN_ROOTS_VERIFIER_SHA256
        or manifest.get("frozen_baseline", {}).get("v2", {}).get(
            "graph_denominator_sha256"
        )
        != CFG_INVENTORY_GRAPH_SHA256
        or manifest.get("frozen_baseline", {}).get("v3", {}).get(
            "graph_denominator_sha256"
        )
        != CFG_V3_INVENTORY_GRAPH_SHA256
    ):
        raise ValueError("CFG proven-root promotion manifest contract changed")
    extension = payload.get("extension")
    producer_denominator = payload.get("producer_denominator")
    if (
        payload.get("schema") != "rom-cfg-proven-roots-v1"
        or payload.get("rom") != expected_rom
        or payload.get("frozen_baseline") != manifest.get("frozen_baseline")
        or payload.get("root_denominator_sha256")
        != CFG_PROVEN_ROOTS_ROOT_SHA256
        or not isinstance(payload.get("roots"), list)
        or len(payload["roots"]) != 2
        or not isinstance(producer_denominator, dict)
        or producer_denominator.get("denominator_sha256")
        != CFG_PROVEN_ROOTS_PRODUCER_SHA256
        or not isinstance(extension, dict)
        or extension.get("summary")
        != CFG_PROVEN_ROOTS_EXPECTED_EXTENSION_SUMMARY
        or extension.get("cross_edge_summary")
        != CFG_PROVEN_ROOTS_EXPECTED_CROSS_SUMMARY
        or extension.get("frontier_denominator_sha256")
        != CFG_PROVEN_ROOTS_FRONTIER_SHA256
        or extension.get("cross_edge_denominator_sha256")
        != CFG_PROVEN_ROOTS_CROSS_EDGE_SHA256
        or payload.get("graph_denominator_sha256")
        != CFG_PROVEN_ROOTS_GRAPH_SHA256
        or payload.get("scope") != CFG_PROVEN_ROOTS_EXPECTED_SCOPE
    ):
        raise ValueError("CFG proven-root payload contract changed")
    report = verify_rom_cfg_proven_roots(root, artifact_dir)
    if report != CFG_PROVEN_ROOTS_EXPECTED_REPORT:
        raise ValueError(
            f"CFG proven-root independent verification failed: {report}"
        )

    baseline_segments = atomize_claims(len(rom), baseline_claims)
    unknown_ranges = [
        tuple(segment["range"])
        for segment in baseline_segments
        if segment["primary_class"] == "unknown"
    ]
    blocks = extension.get("blocks")
    if not isinstance(blocks, list) or len(blocks) != 1_203:
        raise ValueError("CFG proven-root block denominator changed")
    source_pieces: list[dict[str, Any]] = []
    unknown_index = 0
    previous_block_end = -1
    for block in blocks:
        if not isinstance(block, dict):
            raise ValueError("CFG proven-root block is not an object")
        mode = block.get("mode")
        value = block.get("range")
        if (
            mode != "thumb"
            or not isinstance(value, list)
            or len(value) != 2
            or not all(isinstance(item, int) for item in value)
        ):
            raise ValueError("CFG proven-root block schema changed")
        start, end = value
        block_id = block.get("id")
        if (
            block_id != f"block-thumb-{start:06x}"
            or start < previous_block_end
            or start < 0
            or start >= end
            or end > len(rom)
            or block.get("bytes_sha256") != _sha256(rom[start:end])
            or not isinstance(block.get("instruction_count"), int)
            or block["instruction_count"] <= 0
        ):
            raise ValueError(
                f"CFG proven-root block bytes or identity changed: {block_id}"
            )
        previous_block_end = end
        while (
            unknown_index < len(unknown_ranges)
            and unknown_ranges[unknown_index][1] <= start
        ):
            unknown_index += 1
        scan_index = unknown_index
        while scan_index < len(unknown_ranges) and unknown_ranges[scan_index][0] < end:
            unknown_start, unknown_end = unknown_ranges[scan_index]
            piece_start = max(start, unknown_start)
            piece_end = min(end, unknown_end)
            if piece_start < piece_end:
                source_pieces.append(
                    {
                        "mode": mode,
                        "block_id": block_id,
                        "range": [piece_start, piece_end],
                    }
                )
            scan_index += 1
    if len(source_pieces) != CFG_PROVEN_ROOTS_PROMOTED_SOURCE_PIECES:
        raise ValueError(
            "CFG proven-root unknown-intersection denominator changed: "
            f"{len(source_pieces)}"
        )
    merged: list[dict[str, Any]] = []
    for piece in source_pieces:
        start, end = piece["range"]
        if (
            merged
            and merged[-1]["mode"] == piece["mode"]
            and merged[-1]["range"][1] == start
        ):
            merged[-1]["range"][1] = end
            merged[-1]["source_blocks"].append(
                {"block_id": piece["block_id"], "range": piece["range"]}
            )
        else:
            if merged and start < merged[-1]["range"][1]:
                raise ValueError("CFG proven-root promoted ranges overlap")
            merged.append(
                {
                    "mode": piece["mode"],
                    "range": [start, end],
                    "source_blocks": [
                        {"block_id": piece["block_id"], "range": piece["range"]}
                    ],
                }
            )
    promoted_code_bytes = sum(
        item["range"][1] - item["range"][0] for item in merged
    )
    if (
        len(merged) != CFG_PROVEN_ROOTS_PROMOTED_CODE_CLAIM_COUNT
        or promoted_code_bytes != CFG_PROVEN_ROOTS_PROMOTED_CODE_BYTES
    ):
        raise ValueError(
            "CFG proven-root promoted code denominator changed: "
            f"claims={len(merged)}, bytes={promoted_code_bytes}"
        )
    code_claims = []
    for index, item in enumerate(merged):
        start, end = item["range"]
        code_claims.append(
            {
                "id": f"cfg-proven-roots-thumb-{index:04d}-{start:06x}",
                "range": [start, end],
                "role": "primary",
                "primary_class": "armv4t_cfg_proven_roots_reachable_thumb_code",
                "claim_kind": "cfg_proven_roots_reachable_instruction_bytes",
                "mode": "thumb",
                "source_block_count": len(item["source_blocks"]),
                "source_blocks": item["source_blocks"],
                "fixed_root_count": 2,
                "fixed_direct_producer_count": 3,
                "graph_denominator_sha256": CFG_PROVEN_ROOTS_GRAPH_SHA256,
                "promoted_from_primary_class": "unknown",
                "runtime_reachability_claimed": False,
                "global_code_map_claimed": False,
                "bytes_sha256": _sha256(rom[start:end]),
                "evidence_path": (
                    CFG_PROVEN_ROOTS_ARTIFACT / "rom-cfg-proven-roots.json"
                ).as_posix(),
                "evidence_sha256": CFG_PROVEN_ROOTS_PAYLOAD_SHA256,
                "evidence_selector": "/extension/blocks",
                "promotion_manifest_path": (
                    CFG_PROVEN_ROOTS_ARTIFACT / "manifest.json"
                ).as_posix(),
                "promotion_manifest_sha256": CFG_PROVEN_ROOTS_MANIFEST_SHA256,
                "independent_verifier_path": CFG_PROVEN_ROOTS_VERIFIER.as_posix(),
                "independent_verifier_sha256": CFG_PROVEN_ROOTS_VERIFIER_SHA256,
                "promotion_batch": "cfg-proven-roots-v1",
                "limitations": [
                    "Only current-unknown bytes reached from the two fixed direct-call roots are promoted.",
                    "The frozen v2/v3 graph is opaque; 27 indirect targets and one decode failure remain open.",
                    "Natural runtime reachability and a global code map are not claimed.",
                ],
            }
        )

    producer_records = producer_denominator.get("producers")
    expected_producers = [
        (0x73688, 0x81B70, "0ef072fa"),
        (0x7443C, 0x722A8, "fdf734ff"),
        (0x74918, 0x722A8, "fdf7c6fc"),
    ]
    if not isinstance(producer_records, list) or len(producer_records) != 3:
        raise ValueError("CFG proven-root producer denominator changed")
    producer_claims = []
    for index, (record, expected) in enumerate(
        zip(producer_records, expected_producers, strict=True)
    ):
        if not isinstance(record, dict):
            raise ValueError("CFG proven-root producer is not an object")
        start, target, raw_hex = expected
        end = start + 4
        unknown_bytes = sum(
            max(0, min(end, unknown_end) - max(start, unknown_start))
            for unknown_start, unknown_end in unknown_ranges
            if unknown_start < end and start < unknown_end
        )
        if (
            record.get("file_offset") != start
            or record.get("target_file_offset") != target
            or record.get("raw_hex") != raw_hex
            or rom[start:end].hex() != raw_hex
            or record.get("bytes_sha256") != _sha256(rom[start:end])
            or unknown_bytes != 4
        ):
            raise ValueError(
                f"CFG proven-root producer claim changed at 0x{start:06X}"
            )
        if any(
            start < claim["range"][1] and claim["range"][0] < end
            for claim in code_claims
        ):
            raise ValueError("CFG proven-root producer overlaps reachable delta code")
        producer_claims.append(
            {
                "id": f"cfg-proven-roots-producer-{index:02d}-{start:06x}",
                "range": [start, end],
                "role": "primary",
                "primary_class": "thumb_bl_direct_call_producer",
                "claim_kind": "cfg_proven_roots_direct_thumb_bl_producer",
                "mode": "thumb",
                "target_file_offset": target,
                "producer_denominator_sha256": CFG_PROVEN_ROOTS_PRODUCER_SHA256,
                "promoted_from_primary_class": "unknown",
                "runtime_reachability_claimed": False,
                "global_code_map_claimed": False,
                "global_thumb_bl_denominator_claimed": False,
                "bytes_sha256": _sha256(rom[start:end]),
                "evidence_path": (
                    CFG_PROVEN_ROOTS_ARTIFACT / "rom-cfg-proven-roots.json"
                ).as_posix(),
                "evidence_sha256": CFG_PROVEN_ROOTS_PAYLOAD_SHA256,
                "evidence_selector": f"/producer_denominator/producers/{index}",
                "promotion_manifest_path": (
                    CFG_PROVEN_ROOTS_ARTIFACT / "manifest.json"
                ).as_posix(),
                "promotion_manifest_sha256": CFG_PROVEN_ROOTS_MANIFEST_SHA256,
                "independent_verifier_path": CFG_PROVEN_ROOTS_VERIFIER.as_posix(),
                "independent_verifier_sha256": CFG_PROVEN_ROOTS_VERIFIER_SHA256,
                "promotion_batch": "cfg-proven-roots-v1",
                "limitations": [
                    "This proves one aligned Thumb BL producer targeting the two fixed roots, not natural execution.",
                    "The denominator is complete only for BL instructions targeting these two roots, not for all ROM code.",
                ],
            }
        )
    if (
        len(producer_claims) != CFG_PROVEN_ROOTS_PRODUCER_CLAIM_COUNT
        or sum(claim["range"][1] - claim["range"][0] for claim in producer_claims)
        != CFG_PROVEN_ROOTS_PRODUCER_BYTES
    ):
        raise ValueError("CFG proven-root producer promotion denominator changed")
    return code_claims + producer_claims


def _cfg_proven_roots_v2_claims(
    root: Path,
    rom: bytes,
    existing_claims: Iterable[dict[str, Any]],
) -> list[dict[str, Any]]:
    """Promote current-unknown bytes proven by the second direct-call root batch."""

    root = Path(root).resolve(strict=True)
    baseline_claims = list(existing_claims)
    kinds = {
        "cfg_proven_roots_v2_reachable_instruction_bytes",
        "cfg_proven_roots_v2_direct_thumb_bl_producer",
    }
    if any(claim.get("claim_kind") in kinds for claim in baseline_claims):
        raise ValueError(
            "CFG proven-root v2 claims must be derived from a pre-v2 baseline"
        )
    if not any(
        claim.get("claim_kind")
        in {
            "cfg_proven_roots_reachable_instruction_bytes",
            "cfg_proven_roots_direct_thumb_bl_producer",
        }
        for claim in baseline_claims
    ):
        raise ValueError("CFG proven-root v2 baseline is missing proven-roots-v1 claims")
    if len(rom) != 6_291_456 or _sha256(rom) != ROM_SHA256:
        raise ValueError("CFG proven-root v2 ROM identity changed")

    artifact_dir = (root / CFG_PROVEN_ROOTS_V2_ARTIFACT).absolute()
    try:
        resolved_artifact = artifact_dir.resolve(strict=True)
        resolved_artifact.relative_to(root)
    except (OSError, ValueError) as error:
        raise ValueError(
            "CFG proven-root v2 artifact is missing or outside the repository"
        ) from error
    if resolved_artifact != artifact_dir or not artifact_dir.is_dir():
        raise ValueError(
            "CFG proven-root v2 artifact uses a symlink or is not a directory"
        )
    members = list(artifact_dir.iterdir())
    if (
        {member.name for member in members}
        != {"manifest.json", "rom-cfg-proven-roots-v2.json"}
        or any(member.is_symlink() or not member.is_file() for member in members)
    ):
        raise ValueError("CFG proven-root v2 artifact file set changed")

    verifier_path = (root / CFG_PROVEN_ROOTS_V2_VERIFIER).absolute()
    try:
        resolved_verifier = verifier_path.resolve(strict=True)
        resolved_verifier.relative_to(root)
    except (OSError, ValueError) as error:
        raise ValueError("CFG proven-root v2 verifier is missing") from error
    if resolved_verifier != verifier_path or not verifier_path.is_file():
        raise ValueError("CFG proven-root v2 verifier uses a symlink or is not a file")
    if _sha256_file(verifier_path) != CFG_PROVEN_ROOTS_V2_VERIFIER_SHA256:
        raise ValueError("CFG proven-root v2 verifier SHA-256 changed")

    manifest_path = artifact_dir / "manifest.json"
    payload_path = artifact_dir / "rom-cfg-proven-roots-v2.json"
    manifest_raw = manifest_path.read_bytes()
    payload_raw = payload_path.read_bytes()
    if _sha256(manifest_raw) != CFG_PROVEN_ROOTS_V2_MANIFEST_SHA256:
        raise ValueError("CFG proven-root v2 manifest SHA-256 changed")
    if (
        len(payload_raw) != CFG_PROVEN_ROOTS_V2_PAYLOAD_SIZE
        or _sha256(payload_raw) != CFG_PROVEN_ROOTS_V2_PAYLOAD_SHA256
    ):
        raise ValueError("CFG proven-root v2 payload identity changed")
    manifest = json.loads(manifest_raw)
    payload = json.loads(payload_raw)
    expected_rom = {
        "path": ROM_PATH.as_posix(),
        "size": len(rom),
        "sha256": ROM_SHA256,
    }
    expected_file = {
        "rom-cfg-proven-roots-v2.json": {
            "size": CFG_PROVEN_ROOTS_V2_PAYLOAD_SIZE,
            "sha256": CFG_PROVEN_ROOTS_V2_PAYLOAD_SHA256,
        }
    }
    frozen = manifest.get("frozen_baseline", {})
    if (
        manifest.get("artifact_schema") != "rom-cfg-proven-roots-v2"
        or manifest.get("rom") != expected_rom
        or manifest.get("producer_summary")
        != {
            "count": 5,
            "denominator_sha256": CFG_PROVEN_ROOTS_V2_PRODUCER_SHA256,
        }
        or manifest.get("root_count") != 3
        or manifest.get("root_denominator_sha256")
        != CFG_PROVEN_ROOTS_V2_ROOT_SHA256
        or manifest.get("extension_summary")
        != CFG_PROVEN_ROOTS_V2_EXPECTED_EXTENSION_SUMMARY
        or manifest.get("cross_edge_summary")
        != CFG_PROVEN_ROOTS_V2_EXPECTED_CROSS_SUMMARY
        or manifest.get("graph_denominator_sha256")
        != CFG_PROVEN_ROOTS_V2_GRAPH_SHA256
        or manifest.get("scope") != CFG_PROVEN_ROOTS_V2_EXPECTED_SCOPE
        or manifest.get("files") != expected_file
        or manifest.get("implementation", {}).get("verifier_sha256")
        != CFG_PROVEN_ROOTS_V2_VERIFIER_SHA256
        or frozen.get("v2", {}).get("graph_denominator_sha256")
        != CFG_INVENTORY_GRAPH_SHA256
        or frozen.get("v3", {}).get("graph_denominator_sha256")
        != CFG_V3_INVENTORY_GRAPH_SHA256
        or frozen.get("proven_roots_v1", {}).get("graph_denominator_sha256")
        != CFG_PROVEN_ROOTS_GRAPH_SHA256
    ):
        raise ValueError("CFG proven-root v2 promotion manifest contract changed")
    extension = payload.get("extension")
    producer_denominator = payload.get("producer_denominator")
    if (
        payload.get("schema") != "rom-cfg-proven-roots-v2"
        or payload.get("rom") != expected_rom
        or payload.get("frozen_baseline") != manifest.get("frozen_baseline")
        or payload.get("root_denominator_sha256")
        != CFG_PROVEN_ROOTS_V2_ROOT_SHA256
        or not isinstance(payload.get("roots"), list)
        or len(payload["roots"]) != 3
        or not isinstance(producer_denominator, dict)
        or producer_denominator.get("denominator_sha256")
        != CFG_PROVEN_ROOTS_V2_PRODUCER_SHA256
        or not isinstance(extension, dict)
        or extension.get("summary")
        != CFG_PROVEN_ROOTS_V2_EXPECTED_EXTENSION_SUMMARY
        or extension.get("cross_edge_summary")
        != CFG_PROVEN_ROOTS_V2_EXPECTED_CROSS_SUMMARY
        or extension.get("frontier_denominator_sha256")
        != CFG_PROVEN_ROOTS_V2_FRONTIER_SHA256
        or extension.get("cross_edge_denominator_sha256")
        != CFG_PROVEN_ROOTS_V2_CROSS_EDGE_SHA256
        or payload.get("graph_denominator_sha256")
        != CFG_PROVEN_ROOTS_V2_GRAPH_SHA256
        or payload.get("scope") != CFG_PROVEN_ROOTS_V2_EXPECTED_SCOPE
    ):
        raise ValueError("CFG proven-root v2 payload contract changed")
    report = verify_rom_cfg_proven_roots_v2(root, artifact_dir)
    if report != CFG_PROVEN_ROOTS_V2_EXPECTED_REPORT:
        raise ValueError(
            f"CFG proven-root v2 independent verification failed: {report}"
        )

    baseline_segments = atomize_claims(len(rom), baseline_claims)
    unknown_ranges = [
        tuple(segment["range"])
        for segment in baseline_segments
        if segment["primary_class"] == "unknown"
    ]
    blocks = extension.get("blocks")
    if not isinstance(blocks, list) or len(blocks) != 835:
        raise ValueError("CFG proven-root v2 block denominator changed")
    source_pieces: list[dict[str, Any]] = []
