def _u8_indexed_u8_triplet_lookup_claims(
    root: Path,
    rom: bytes,
    existing_claims: Iterable[dict[str, Any]],
) -> list[dict[str, Any]]:
    """Promote only the accepted pointer literal and five u8 triplet rows."""

    root = Path(root).resolve(strict=True)
    baseline = list(existing_claims)
    claim_kinds = {spec[3] for spec in U8_TRIPLET_CLAIM_SPECS}
    if any(
        claim.get("promotion_batch") == U8_TRIPLET_BATCH
        or claim.get("claim_kind") in claim_kinds
        for claim in baseline
    ):
        raise ValueError(
            "u8 triplet claims require a pre-promotion baseline; "
            "batch is already present"
        )
    if len(rom) != 6_291_456 or _sha256(rom) != ROM_SHA256:
        raise ValueError("u8 triplet ROM identity changed")

    artifact = _checked_artifact_directory(
        root,
        U8_TRIPLET_ARTIFACT,
        {
            "manifest.json",
            U8_TRIPLET_PAYLOAD_NAME,
            U8_TRIPLET_BINARY_NAME,
        },
        label="u8 triplet artifact",
    )
    manifest_path = _checked_repository_file(
        root,
        U8_TRIPLET_ARTIFACT / "manifest.json",
        U8_TRIPLET_MANIFEST_SHA256,
        expected_size=U8_TRIPLET_MANIFEST_SIZE,
        label="u8 triplet manifest",
    )
    payload_path = _checked_repository_file(
        root,
        U8_TRIPLET_ARTIFACT / U8_TRIPLET_PAYLOAD_NAME,
        U8_TRIPLET_PAYLOAD_SHA256,
        expected_size=U8_TRIPLET_PAYLOAD_SIZE,
        label="u8 triplet payload",
    )
    binary_path = _checked_repository_file(
        root,
        U8_TRIPLET_ARTIFACT / U8_TRIPLET_BINARY_NAME,
        U8_TRIPLET_BINARY_SHA256,
        expected_size=U8_TRIPLET_BINARY_SIZE,
        label="u8 triplet binary",
    )
    for path, expected_sha, label in (
        (
            U8_TRIPLET_EXPORTER,
            U8_TRIPLET_EXPORTER_SHA256,
            "u8 triplet exporter",
        ),
        (
            U8_TRIPLET_VERIFIER,
            U8_TRIPLET_VERIFIER_SHA256,
            "u8 triplet verifier",
        ),
        (
            U8_TRIPLET_BUNDLE_VERIFIER,
            U8_TRIPLET_BUNDLE_VERIFIER_SHA256,
            "u8 triplet bundle verifier",
        ),
        (
            U8_TRIPLET_BUNDLE_TEST,
            U8_TRIPLET_BUNDLE_TEST_SHA256,
            "u8 triplet bundle verifier test",
        ),
        (
            U8_TRIPLET_EXPORTER_TEST,
            U8_TRIPLET_EXPORTER_TEST_SHA256,
            "u8 triplet exporter test",
        ),
        (
            U8_TRIPLET_VERIFIER_TEST,
            U8_TRIPLET_VERIFIER_TEST_SHA256,
            "u8 triplet verifier test",
        ),
    ):
        _checked_repository_file(root, path, expected_sha, label=label)

    manifest_raw = manifest_path.read_bytes()
    payload_raw = payload_path.read_bytes()
    try:
        manifest = json.loads(manifest_raw)
        payload = json.loads(payload_raw)
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise ValueError("u8 triplet artifact JSON is invalid") from error
    if (
        not isinstance(manifest, dict)
        or not isinstance(payload, dict)
        or manifest_raw != _canonical_json_bytes(manifest)
        or payload_raw != _canonical_json_bytes(payload)
    ):
        raise ValueError("u8 triplet artifact JSON is not canonical")

    expected_implementation = {
        "exporter": {
            "path": U8_TRIPLET_EXPORTER.as_posix(),
            "sha256": U8_TRIPLET_EXPORTER_SHA256,
        },
        "exporter_tests": {
            "path": U8_TRIPLET_EXPORTER_TEST.as_posix(),
            "sha256": U8_TRIPLET_EXPORTER_TEST_SHA256,
        },
        "verifier": {
            "path": U8_TRIPLET_VERIFIER.as_posix(),
            "sha256": U8_TRIPLET_VERIFIER_SHA256,
        },
        "verifier_tests": {
            "path": U8_TRIPLET_VERIFIER_TEST.as_posix(),
            "sha256": U8_TRIPLET_VERIFIER_TEST_SHA256,
        },
    }
    projection = manifest.get("coverage_projection")
    payload_projection = payload.get("coverage_projection")
    if (
        manifest.get("schema") != "git-artifact-promotion-v1"
        or manifest.get("artifact_schema") != U8_TRIPLET_BATCH
        or manifest.get("artifact_status") != "accepted"
        or manifest.get("files")
        != {
            U8_TRIPLET_BINARY_NAME: {
                "sha256": U8_TRIPLET_BINARY_SHA256,
                "size": U8_TRIPLET_BINARY_SIZE,
            },
            U8_TRIPLET_PAYLOAD_NAME: {
                "sha256": U8_TRIPLET_PAYLOAD_SHA256,
                "size": U8_TRIPLET_PAYLOAD_SIZE,
            },
        }
        or manifest.get("implementation") != expected_implementation
        or payload.get("implementation") != expected_implementation
        or payload.get("schema") != U8_TRIPLET_BATCH
        or manifest.get("rom") != payload.get("rom")
        or manifest.get("coverage_baseline") != payload.get("coverage_baseline")
        or manifest.get("promotion") != payload.get("promotion")
        or manifest.get("scope") != payload.get("scope")
        or manifest.get("non_claims") != payload.get("non_claims")
        or not isinstance(projection, dict)
        or projection.get("claim_count") != 2
        or projection.get("byte_count") != U8_TRIPLET_BINARY_SIZE
        or projection.get("range_vector_sha256")
        != U8_TRIPLET_RANGE_VECTOR_SHA256
        or projection.get("packed_bytes_sha256")
        != U8_TRIPLET_BINARY_SHA256
        or projection.get("claim_denominator_sha256")
        != U8_TRIPLET_CLAIM_DENOMINATOR_SHA256
        or not isinstance(payload_projection, dict)
        or payload_projection.get("baseline")
        != payload.get("coverage_baseline")
        or payload_projection.get("promoted_byte_size")
        != U8_TRIPLET_BINARY_SIZE
        or payload_projection.get("promoted_ranges")
        != [list(spec[1]) for spec in U8_TRIPLET_CLAIM_SPECS]
        or payload_projection.get("expected_delta")
        != {"classified": 19, "unknown": -19, "claims": 2, "segments": 2}
        or payload_projection.get("current_unknown_only") is not True
        or payload_projection.get("code_repromotion") is not False
        or payload_projection.get("literal_pools_claimed") is not False
        or payload_projection.get("right_gap_claimed") is not False
    ):
        raise ValueError("u8 triplet promotion contract changed")

    try:
        report = verify_rom_u8_indexed_u8_triplet_lookup_bundle(root, artifact)
    except Exception as error:
        raise ValueError(
            f"u8 triplet independent verification failed: {error}"
        ) from error
    verification = manifest.get("verification")
    expected_report = (
        verification.get("report") if isinstance(verification, dict) else None
    )
    if (
        not isinstance(report, dict)
        or report.get("schema")
        != "rom-u8-indexed-u8-triplet-lookup-bundle-verification-v1"
        or report.get("verified") is not True
        or report.get("errors") != []
        or report.get("artifact_schema") != U8_TRIPLET_BATCH
        or report.get("artifact_status") != "accepted"
        or report.get("artifact_bundle_verified") is not True
        or report.get("legacy_receipt_verified") is not True
        or report.get("live_coverage_verified") is not False
        or report.get("rom_sha256") != ROM_SHA256
        or report.get("promotion_bytes") != U8_TRIPLET_BINARY_SIZE
        or report.get("promotion_claim_count") != 2
        or report.get("promotion_range_count") != 2
        or report.get("promotion_range_vector_sha256")
        != U8_TRIPLET_RANGE_VECTOR_SHA256
        or report.get("promotion_packed_sha256")
        != U8_TRIPLET_BINARY_SHA256
        or report.get("consumer_instruction_count") != 134
        or report.get("consumer_block_count") != 28
        or report.get("consumer_frontier_count") != 0
        or report.get("table_record_count") != 5
        or report.get("legacy_verifier_sha256") != U8_TRIPLET_VERIFIER_SHA256
        or report.get("bundle_verifier_sha256")
        != U8_TRIPLET_BUNDLE_VERIFIER_SHA256
        or report.get("legacy_report") != expected_report
        or manifest.get("verifier") != verification
        or not isinstance(verification, dict)
        or verification.get("exit_code") != 0
        or verification.get("verifier_sha256") != U8_TRIPLET_VERIFIER_SHA256
    ):
        raise ValueError(
            f"u8 triplet independent verification failed: {report}"
        )

    promotion = payload.get("promotion")
    expected_ranges = [list(spec[1]) for spec in U8_TRIPLET_CLAIM_SPECS]
    if (
        not isinstance(promotion, dict)
        or promotion.get("ranges") != expected_ranges
        or promotion.get("byte_size") != U8_TRIPLET_BINARY_SIZE
        or promotion.get("range_vector_sha256")
        != U8_TRIPLET_RANGE_VECTOR_SHA256
        or promotion.get("packed_sha256") != U8_TRIPLET_BINARY_SHA256
        or [row.get("range") for row in promotion.get("claims", [])]
        != expected_ranges
    ):
        raise ValueError("u8 triplet promotion denominator changed")
    packed = b"".join(
        rom[start:end] for start, end in map(tuple, expected_ranges)
    )
    if (
        binary_path.read_bytes() != packed
        or _sha256(packed) != U8_TRIPLET_BINARY_SHA256
    ):
        raise ValueError("u8 triplet binary denominator changed")

    try:
        claims = expected_rom_u8_indexed_u8_triplet_lookup_claims(
            payload,
            manifest,
            manifest_sha256=U8_TRIPLET_MANIFEST_SHA256,
        )
    except Exception as error:
        raise ValueError(
            f"u8 triplet coverage projection failed: {error}"
        ) from error
    projected = [
        (
            claim.get("id"),
            tuple(claim.get("range", [])),
            claim.get("primary_class"),
            claim.get("claim_kind"),
            claim.get("mode"),
        )
        for claim in claims
    ]
    if projected != list(U8_TRIPLET_CLAIM_SPECS):
        raise ValueError("u8 triplet coverage claim denominator changed")
    if any(
        claim.get("limitations") != [U8_TRIPLET_COVERAGE_LIMITATION]
        for claim in claims
    ):
        raise ValueError("u8 triplet coverage limitations changed")

    primary = [claim for claim in baseline if claim.get("role") == "primary"]
    for claim in claims:
        start, end = _validated_range(claim, len(rom))
        if claim.get("bytes_sha256") != _sha256(rom[start:end]):
            raise ValueError(f"u8 triplet claim bytes changed: {claim.get('id')}")
        if any(
            other_start < end and start < other_end
            for other in primary
            for other_start, other_end in [_validated_range(other, len(rom))]
        ):
            raise ValueError(
                f"u8 triplet unknown projection overlap: {claim.get('id')}"
            )
    return claims


