def _training_text_script_claims(
    root: Path, rom: bytes
) -> list[dict[str, Any]]:
    """Classify the 44 fixed-slot training scripts consumed by the interpreter."""

    if _sha256(rom) != ROM_SHA256:
        raise ValueError("training-text-script ROM SHA-256 changed")
    artifact = (root / TRAINING_TEXT_SCRIPT_ARTIFACT).absolute()
    manifest_path = artifact / "manifest.json"
    payload_path = (root / TRAINING_TEXT_SCRIPT_PAYLOAD).absolute()
    bundle_path = (root / TRAINING_TEXT_SCRIPT_BUNDLE).absolute()
    verifier_path = (root / TRAINING_TEXT_SCRIPT_VERIFIER).absolute()
    for path, label in (
        (artifact, "artifact"),
        (manifest_path, "manifest"),
        (payload_path, "payload"),
        (bundle_path, "bundle"),
        (verifier_path, "verifier"),
    ):
        try:
            resolved = path.resolve(strict=True)
            resolved.relative_to(root)
        except (OSError, ValueError) as error:
            raise ValueError(f"training-text-script {label} is invalid") from error
        if resolved != path or path.is_symlink():
            raise ValueError(f"training-text-script {label} uses a symlink")
    if not artifact.is_dir() or any(path.is_symlink() for path in artifact.rglob("*")):
        raise ValueError("training-text-script artifact tree is unsafe")
    if {
        path.relative_to(artifact).as_posix()
        for path in artifact.rglob("*")
        if path.is_file()
    } != {"manifest.json", payload_path.name, bundle_path.name}:
        raise ValueError("training-text-script artifact file denominator changed")
    for path, digest, label in (
        (manifest_path, TRAINING_TEXT_SCRIPT_MANIFEST_SHA256, "manifest"),
        (payload_path, TRAINING_TEXT_SCRIPT_PAYLOAD_SHA256, "payload"),
        (bundle_path, TRAINING_TEXT_SCRIPT_BUNDLE_SHA256, "bundle"),
        (verifier_path, TRAINING_TEXT_SCRIPT_VERIFIER_SHA256, "verifier"),
    ):
        if _sha256_file(path) != digest:
            raise ValueError(f"training-text-script {label} changed")

    manifest = json.loads(manifest_path.read_bytes())
    payload = json.loads(payload_path.read_bytes())
    bundle = bundle_path.read_bytes()
    expected_summary = {
        "pointer_table_count": 1,
        "pointer_slot_count": 45,
        "pointer_table_bytes": 180,
        "null_slot_count": 1,
        "non_null_slot_count": 44,
        "unique_target_count": 44,
        "command_record_count": 44,
        "command_count": 264,
        "embedded_renderer_text_count": 44,
        "embedded_renderer_text_bytes": 1_889,
        "record_bytes": 2_505,
        "classified_range_count": 44,
        "classified_bytes": 2_505,
        "inter_record_gap_bytes": 0,
        "range_overlap_bytes": 0,
        "parse_failure_count": 0,
        "packed_bytes": 2_505,
    }
    implementation = payload.get("implementation")
    expected_verification = {
        "schema": "rom-training-text-script-inventory-verification-v1",
        "command": [
            "python3",
            "tools/verify_rom_training_text_script_inventory.py",
            "--root",
            ".",
            "--artifact-dir",
            TRAINING_TEXT_SCRIPT_ARTIFACT.as_posix(),
        ],
        "verifier_sha256": TRAINING_TEXT_SCRIPT_VERIFIER_SHA256,
    }
    if (
        manifest.get("schema")
        != "rom-training-text-script-inventory-v1-artifact-manifest-v1"
        or manifest.get("artifact_schema")
        != "rom-training-text-script-inventory-v1"
        or manifest.get("files")
        != {
            payload_path.name: TRAINING_TEXT_SCRIPT_PAYLOAD_SHA256,
            bundle_path.name: TRAINING_TEXT_SCRIPT_BUNDLE_SHA256,
        }
        or manifest.get("producer") != implementation
        or manifest.get("scope") != TRAINING_TEXT_SCRIPT_SCOPE
        or manifest.get("verification") != expected_verification
    ):
        raise ValueError("training-text-script manifest contract changed")
    if (
        payload.get("schema") != "rom-training-text-script-inventory-v1"
        or payload.get("rom")
        != {"path": ROM_PATH.as_posix(), "size": len(rom), "sha256": ROM_SHA256}
        or payload.get("summary") != expected_summary
        or payload.get("record_range_denominator_sha256")
        != TRAINING_TEXT_SCRIPT_RECORD_DENOMINATOR_SHA256
        or payload.get("command_range_denominator_sha256")
        != TRAINING_TEXT_SCRIPT_COMMAND_DENOMINATOR_SHA256
        or payload.get("command_sequence_sha256")
        != TRAINING_TEXT_SCRIPT_COMMAND_SEQUENCE_SHA256
        or payload.get("command_opcode_counts")
        != {"0": 44, "1": 44, "3": 44, "4": 44, "5": 44, "12": 44}
        or payload.get("scope") != TRAINING_TEXT_SCRIPT_SCOPE
        or payload.get("files")
        != {
            bundle_path.name: {
                "size": 2_505,
                "sha256": TRAINING_TEXT_SCRIPT_BUNDLE_SHA256,
            }
        }
        or not isinstance(implementation, dict)
        or implementation.get("verifier")
        != {
            "path": TRAINING_TEXT_SCRIPT_VERIFIER.as_posix(),
            "sha256": TRAINING_TEXT_SCRIPT_VERIFIER_SHA256,
        }
    ):
        raise ValueError("training-text-script payload denominator changed")

    report = verify_rom_training_text_script_inventory(root, artifact)
    expected_report = {
        "schema": "rom-training-text-script-inventory-verification-v1",
        "verified": True,
        "errors": [],
        **expected_summary,
        "summary": expected_summary,
        "bundle_sha256": TRAINING_TEXT_SCRIPT_BUNDLE_SHA256,
        "record_range_denominator_sha256": (
            TRAINING_TEXT_SCRIPT_RECORD_DENOMINATOR_SHA256
        ),
        "command_range_denominator_sha256": (
            TRAINING_TEXT_SCRIPT_COMMAND_DENOMINATOR_SHA256
        ),
    }
    if report != expected_report:
        raise ValueError(
            f"training-text-script independent verifier failed: {report}"
        )

    table = payload.get("pointer_table")
    if (
        not isinstance(table, dict)
        or table.get("semantic_type")
        != "training_text_command_script_pointer_table"
        or table.get("range") != [0x59A104, 0x59A1B8]
        or table.get("entry_count") != 45
        or table.get("entry_size") != 4
        or table.get("null_slot_indices") != [0]
        or table.get("non_null_slot_indices") != list(range(1, 45))
        or table.get("sha256") != TRAINING_TEXT_SCRIPT_TABLE_SHA256
        or _sha256(rom[0x59A104:0x59A1B8])
        != TRAINING_TEXT_SCRIPT_TABLE_SHA256
    ):
        raise ValueError("training-text-script pointer-table denominator changed")
    records = payload.get("records")
    classified = payload.get("classified_ranges")
    if not isinstance(records, list) or len(records) != 44:
        raise ValueError("training-text-script record denominator changed")
    if not isinstance(classified, list) or len(classified) != 44:
        raise ValueError("training-text-script classified denominator changed")
    records_by_id = {
        record.get("record_id"): record
        for record in records
        if isinstance(record, dict) and isinstance(record.get("record_id"), str)
    }
    if len(records_by_id) != 44:
        raise ValueError("training-text-script record IDs changed")

    claims: list[dict[str, Any]] = []
    record_ranges: list[list[int]] = []
    command_ranges: list[list[int]] = []
    command_sequence: list[list[int]] = []
    packed_cursor = 0
    previous_end = 0x7554
    expected_opcodes = [1, 5, 4, 12, 3, 0]
    for index, item in enumerate(classified):
        slot = index + 1
        record_id = f"training-text-script-{slot:02d}"
        record = records_by_id.get(record_id)
        if not isinstance(item, dict) or not isinstance(record, dict):
            raise ValueError(f"training-text-script record changed: {slot}")
        value = item.get("range")
        packed = item.get("packed_range")
        if (
            item.get("range_id") != record_id
            or item.get("kind") != "training_text_command_script"
            or item.get("slot_index") != slot
            or record.get("record_id") != record_id
            or record.get("slot_index") != slot
            or record.get("opcode_sequence") != expected_opcodes
            or value != record.get("range")
            or packed != record.get("packed_range")
            or not isinstance(value, list)
            or len(value) != 2
            or not all(isinstance(boundary, int) for boundary in value)
            or not isinstance(packed, list)
            or len(packed) != 2
            or not all(isinstance(boundary, int) for boundary in packed)
        ):
            raise ValueError(f"training-text-script schema changed: {slot}")
        start, end = value
        packed_start, packed_end = packed
        raw = rom[start:end]
        if (
            start != previous_end
            or not 0 <= start < end <= len(rom)
            or packed_start != packed_cursor
            or packed_end - packed_start != end - start
            or item.get("size") != end - start
            or record.get("size") != end - start
            or item.get("sha256") != _sha256(raw)
            or record.get("sha256") != item.get("sha256")
            or bundle[packed_start:packed_end] != raw
        ):
            raise ValueError(f"training-text-script bytes changed: {slot}")
        commands = record.get("commands")
        if not isinstance(commands, list) or len(commands) != 6:
            raise ValueError(f"training-text-script commands changed: {slot}")
        command_cursor = start
        for opcode, command in zip(expected_opcodes, commands):
            if (
                not isinstance(command, dict)
                or command.get("opcode") != opcode
                or not isinstance(command.get("range"), list)
                or len(command["range"]) != 2
                or command["range"][0] != command_cursor
                or not command_cursor < command["range"][1] <= end
            ):
                raise ValueError(
                    f"training-text-script command grammar changed: {slot}"
                )
            command_cursor = command["range"][1]
            command_ranges.append(command["range"])
            command_sequence.append([slot, opcode])
        if command_cursor != end:
            raise ValueError(f"training-text-script command tail changed: {slot}")
        record_ranges.append(value)
        previous_end = end
        packed_cursor = packed_end
        claims.append(
            {
                "id": f"training-text-script-record-{slot:02d}-{start:06x}",
                "range": value,
                "role": "primary",
                "primary_class": "training_text_command_script",
                "claim_kind": "training_text_command_script_bytes",
                "bytes_sha256": item["sha256"],
                "evidence_path": TRAINING_TEXT_SCRIPT_PAYLOAD.as_posix(),
                "evidence_sha256": TRAINING_TEXT_SCRIPT_PAYLOAD_SHA256,
                "evidence_selector": f"/classified_ranges/{index}",
                "promotion_manifest_path": (
                    TRAINING_TEXT_SCRIPT_ARTIFACT / "manifest.json"
                ).as_posix(),
                "promotion_manifest_sha256": (
                    TRAINING_TEXT_SCRIPT_MANIFEST_SHA256
                ),
                "independent_verifier_path": (
                    TRAINING_TEXT_SCRIPT_VERIFIER.as_posix()
                ),
                "independent_verifier_sha256": (
                    TRAINING_TEXT_SCRIPT_VERIFIER_SHA256
                ),
                "record_id": record_id,
                "slot_index": slot,
                "limitations": [
                    "The fixed-slot interpreter consumes this command script; natural execution of every training ID, Unicode decoding, and editing safety remain unclaimed."
                ],
            }
        )
    if (
        previous_end != 0x7F1D
        or packed_cursor != len(bundle)
        or len(bundle) != 2_505
        or _sha256(
            json.dumps(record_ranges, separators=(",", ":")).encode("ascii")
        )
        != TRAINING_TEXT_SCRIPT_RECORD_DENOMINATOR_SHA256
        or _sha256(
            json.dumps(command_ranges, separators=(",", ":")).encode("ascii")
        )
        != TRAINING_TEXT_SCRIPT_COMMAND_DENOMINATOR_SHA256
        or _sha256(
            json.dumps(command_sequence, separators=(",", ":")).encode("ascii")
        )
        != TRAINING_TEXT_SCRIPT_COMMAND_SEQUENCE_SHA256
    ):
        raise ValueError("training-text-script final denominator changed")
    return claims


