    claims: list[dict[str, Any]] = []
    classified_ranges: list[list[int]] = []
    record_ranges: list[list[int]] = []
    packed_cursor = 0
    previous_record_end = 0x542E
    map_count = 0
    record_count = 0
    for index, item in enumerate(classified):
        if not isinstance(item, dict):
            raise ValueError(f"value-range-text item changed: {index}")
        value = item.get("range")
        packed = item.get("packed_range")
        if (
            not isinstance(value, list)
            or len(value) != 2
            or not all(isinstance(boundary, int) for boundary in value)
            or not isinstance(packed, list)
            or len(packed) != 2
            or not all(isinstance(boundary, int) for boundary in packed)
        ):
            raise ValueError(f"value-range-text range schema changed: {index}")
        start, end = value
