def _cfg_consumed_literal_batch_claims(
    root: Path,
    rom: bytes,
    existing_claims: Iterable[dict[str, Any]],
) -> list[dict[str, Any]]:
    """Promote seven disjoint accepted-CFG literal projections as one batch."""

    root = Path(root).resolve(strict=True)
    baseline = list(existing_claims)
    configs = _cfg_consumed_literal_configs()
    batches = {config["batch"] for config in configs}
    kinds = {config["claim_kind"] for config in configs}
    if any(
        claim.get("promotion_batch") in batches
        or claim.get("claim_kind") in kinds
        for claim in baseline
    ):
        raise ValueError("CFG consumed-literal batch is already present")
    if len(rom) != 6_291_456 or _sha256(rom) != ROM_SHA256:
        raise ValueError("CFG consumed-literal ROM identity changed")

    segments = atomize_claims(len(rom), baseline)
    segment_starts = [segment["range"][0] for segment in segments]

    def require_unknown(start: int, end: int) -> None:
        index = bisect.bisect_right(segment_starts, start) - 1
        if index < 0:
            raise ValueError("CFG consumed-literal range escaped coverage")
        segment = segments[index]
        if (
            segment.get("primary_class") != "unknown"
            or segment["range"][0] > start
            or end > segment["range"][1]
        ):
            raise ValueError("CFG consumed-literal range is not complete current unknown or overlaps an owner")

    claims: list[dict[str, Any]] = []
    for config in configs:
        artifact = _checked_artifact_directory(
            root,
            config["artifact"],
            {"manifest.json", config["payload_name"]},
            label=f"CFG consumed-literal {config['label']} artifact",
        )
        for path_key, sha_key, label in (
            ("exporter", "exporter_sha256", "exporter"),
            ("verifier", "verifier_sha256", "verifier"),
            ("test", "test_sha256", "exporter test"),
            ("verifier_test", "verifier_test_sha256", "verifier test"),
        ):
            _checked_repository_file(
                root,
                config[path_key],
                config[sha_key],
                label=f"CFG consumed-literal {config['label']} {label}",
            )
        manifest_raw = (artifact / "manifest.json").read_bytes()
        payload_raw = (artifact / config["payload_name"]).read_bytes()
        if (
            len(manifest_raw) != config["manifest_size"]
            or _sha256(manifest_raw) != config["manifest_sha256"]
            or len(payload_raw) != config["payload_size"]
            or _sha256(payload_raw) != config["payload_sha256"]
        ):
            raise ValueError(f"CFG consumed-literal {config['label']} artifact identity changed")
        try:
            manifest = json.loads(manifest_raw)
            payload = json.loads(payload_raw)
        except json.JSONDecodeError as error:
            raise ValueError("CFG consumed-literal artifact JSON is invalid") from error
        if manifest_raw != _canonical_json_bytes(manifest) or payload_raw != _canonical_json_bytes(payload):
            raise ValueError("CFG consumed-literal artifact JSON is not canonical")
        report = config["verify"](root, artifact)
        denominator_key = config.get("denominator_key", "literal_denominator")
        denominator = payload.get(denominator_key)
        if (
            report.get("contract_ok") is not True
            or report.get(denominator_key) != denominator
            or (
                denominator_key == "literal_denominator"
                and report.get("summary") != payload.get("summary")
            )
        ):
            raise ValueError(f"CFG consumed-literal {config['label']} independent verification failed")
        promotion = payload.get("promotion", {})
        ranges = promotion.get("ranges")
        records = promotion.get("range_records")
        summary = payload.get("summary", denominator if denominator_key == "denominator" else {})
        expected_file = {
            config["payload_name"]: {
                "sha256": config["payload_sha256"],
                "size": config["payload_size"],
            }
        }
        if (
            manifest.get("schema") != "git-artifact-promotion-v1"
            or manifest.get("artifact_schema") != config["artifact_schema"]
            or manifest.get("artifact_status") != "accepted"
            or manifest.get("files") != expected_file
            or payload.get("schema") != config["payload_schema"]
            or (
                manifest.get("summary") != summary
                if denominator_key == "literal_denominator"
                else manifest.get("denominator") != denominator
            )
            or manifest.get("promotion") != promotion
            or promotion.get("promotion_batch") != config["batch"]
            or promotion.get("primary_class") != config["primary_class"]
            or promotion.get("claim_kind") != config["claim_kind"]
            or not isinstance(ranges, list)
            or not isinstance(records, list)
            or len(ranges) != config["claim_count"]
            or len(records) != config["claim_count"]
            or summary.get("merged_target_range_count") != config["claim_count"]
            or summary.get("target_bytes") != config["target_bytes"]
        ):
            raise ValueError(f"CFG consumed-literal {config['label']} promotion contract changed")
        target_words = payload.get("target_words")
        if not isinstance(target_words, list):
            raise ValueError("CFG consumed-literal target denominator changed")
        report_sha256 = _sha256(_canonical_json_bytes(report))
        for index, (interval, record) in enumerate(zip(ranges, records, strict=True)):
            if (
                not isinstance(interval, list)
                or len(interval) != 2
                or not all(isinstance(value, int) for value in interval)
                or record.get("range") != interval
            ):
                raise ValueError("CFG consumed-literal range record changed")
            start, end = interval
            if start >= end or record.get("bytes_sha256") != _sha256(rom[start:end]):
                raise ValueError("CFG consumed-literal range bytes changed")
            require_unknown(start, end)
            covered_words = [
                row
                for row in target_words
                if start <= row.get("target_file_offset", -1) < end
            ]
            if len(covered_words) * 4 != end - start:
                raise ValueError("CFG consumed-literal target/range projection changed")
            claims.append(
                {
                    "id": f"cfg-{config['label']}-consumed-literal-{index:04d}-{start:06x}",
                    "range": [start, end],
                    "role": "primary",
                    "primary_class": config["primary_class"],
                    "claim_kind": config["claim_kind"],
                    "promotion_batch": config["batch"],
                    "promoted_from_primary_class": "unknown",
                    "baseline_unknown_only": True,
                    "bytes_sha256": record["bytes_sha256"],
                    "target_word_count": len(covered_words),
                    "source_instruction_reference_count": sum(
                        len(row.get("source_file_offsets", row.get("sources", [])))
                        for row in covered_words
                    ),
                    "literal_denominator": denominator,
                    "evidence_path": (config["artifact"] / config["payload_name"]).as_posix(),
                    "evidence_sha256": config["payload_sha256"],
                    "evidence_selector": f"/promotion/range_records/{index}",
                    "promotion_manifest_path": (config["artifact"] / "manifest.json").as_posix(),
                    "promotion_manifest_sha256": config["manifest_sha256"],
                    "independent_verifier_path": config["verifier"].as_posix(),
                    "independent_verifier_sha256": config["verifier_sha256"],
                    "independent_verifier_report_sha256": report_sha256,
                    "exporter_path": config["exporter"].as_posix(),
                    "exporter_sha256": config["exporter_sha256"],
                    "upstream_test_path": config["test"].as_posix(),
                    "upstream_test_sha256": config["test_sha256"],
                    "verifier_test_path": config["verifier_test"].as_posix(),
                    "verifier_test_sha256": config["verifier_test_sha256"],
                    "runtime_reachability_claimed": False,
                    "loaded_value_semantics_claimed": False,
                    "adjacent_bytes_claimed": False,
                    "editing_writeback_relocation_safe_claimed": False,
                    "free_or_allocatable_space_claimed": False,
                    "non_claims": [
                        *payload.get("non_claims", []),
                        *(
                            ["No global all-consumer literal denominator is claimed."]
                            if len(payload.get("non_claims", [])) < 4
                            else []
                        ),
                    ],
                    "limitations": [
                        *payload.get("non_claims", []),
                        *(
                            ["No global all-consumer literal denominator is claimed."]
                            if len(payload.get("non_claims", [])) < 4
                            else []
                        ),
                    ],
                }
            )
    claims.sort(key=lambda claim: (claim["range"], claim["id"]))
    if (
        len(claims) != 1_220
        or sum(claim["range"][1] - claim["range"][0] for claim in claims) != 14_492
    ):
        raise ValueError("CFG consumed-literal combined projection changed")
    for previous, current in zip(claims, claims[1:]):
        if previous["range"][1] > current["range"][0]:
            raise ValueError("CFG consumed-literal packets overlap")
    return claims


