def _accepted_consumer_code_slice_packet_claims(
    root: Path, rom: bytes, existing_claims: Iterable[dict[str, Any]]
) -> list[dict[str, Any]]:
    baseline = list(existing_claims)
    segments = atomize_claims(len(rom), baseline)
    existing_ids = {claim["id"] for claim in baseline}
    existing_batches = {claim.get("promotion_batch") for claim in baseline}
    claims: list[dict[str, Any]] = []
    for batch, payload_name, manifest_sha, payload_sha, verifier_name, verifier_sha, verifier in ACCEPTED_CONSUMER_CODE_SLICE_PACKET_SPECS:
        if batch in existing_batches:
            raise ValueError(f"duplicate consumer code-slice promotion batch: {batch}")
        artifact = root / "artifacts" / batch
        manifest_path, payload_path = artifact / "manifest.json", artifact / payload_name
        verifier_path = root / verifier_name
        if _sha256_file(manifest_path) != manifest_sha or _sha256_file(payload_path) != payload_sha or _sha256_file(verifier_path) != verifier_sha:
            raise ValueError(f"consumer code-slice packet identity changed: {batch}")
        report = verifier(root, artifact)
        if report.get("verified") is not True or report.get("errors", []) != []:
            raise ValueError(f"consumer code-slice independent verification failed: {batch}")
        payload = json.loads(payload_path.read_text(encoding="utf-8"))
        if payload.get("schema") != batch or payload.get("artifact_status") != "accepted" or payload.get("coverage", {}).get("sha256") != "24cf30aa8049f961ce71737ca9cacfa42c63771643e8bb6784a8a834ee097987":
            raise ValueError(f"consumer code-slice payload contract changed: {batch}")
        records = payload.get("ranges") if isinstance(payload.get("ranges"), list) else [payload.get("range")]
        for index, record in enumerate(records):
            if not isinstance(record, dict):
                raise ValueError(f"consumer code-slice record missing: {batch}")
            claim_contract = record.get("claim", record)
            start, end = record.get("range", [0, 0])
            if claim_contract.get("primary_class") != "consumer_code_slice" or claim_contract.get("claim_kind") != "consumer_code_slice" or claim_contract.get("promotion_batch") != batch:
                raise ValueError(f"consumer code-slice record semantics changed: {batch}")
            if end <= start or record.get("size") != end - start or _sha256(rom[start:end]) != record.get("bytes_sha256"):
                raise ValueError(f"consumer code-slice raw range changed: {batch}")
            owners = [s for s in segments if s["range"][0] < end and start < s["range"][1]]
            if not owners or owners[0]["range"][0] > start or owners[-1]["range"][1] < end or any(s["primary_class"] != "unknown" or s["primary_claim_ids"] or s["secondary_claim_ids"] for s in owners):
                raise ValueError(f"consumer code-slice target is not current unknown: {batch}")
            claim_id = record["id"]
            if claim_id in existing_ids or any(c["id"] == claim_id for c in claims):
                raise ValueError(f"consumer code-slice claim id collision: {claim_id}")
            claims.append({
                "id": claim_id, "range": [start, end], "role": "primary",
                "primary_class": "consumer_code_slice", "claim_kind": "consumer_code_slice",
                "promotion_batch": batch, "promoted_from_primary_class": "unknown",
                "baseline_unknown_only": True, "bytes_sha256": record["bytes_sha256"],
                "artifact_record_id": record["id"], "evidence_path": f"artifacts/{batch}/{payload_name}",
                "evidence_sha256": payload_sha, "evidence_selector": f"/ranges/{index}" if "ranges" in payload else "/range",
                "promotion_manifest_path": f"artifacts/{batch}/manifest.json", "promotion_manifest_sha256": manifest_sha,
                "independent_verifier_path": verifier_name, "independent_verifier_sha256": verifier_sha,
                "independent_verifier_report_sha256": _sha256(_canonical_json_bytes(report)),
                "instruction_only_claimed": False, "runtime_reachability_claimed": False,
                "safe_editing": False, "allocatable": False, "limitations": payload.get("limitations", []),
            })
    if len(claims) != 5 or sum(c["range"][1] - c["range"][0] for c in claims) != 2120:
        raise ValueError("consumer code-slice packet denominator changed")
    return claims


