FAST_AUDIT_REPLAY_VERIFIER = Path(
    "tools/verify_rom_fast_audit_four_packet_coverage.py"
)
FAST_AUDIT_REPLAY_VERIFIER_SHA256 = (
    "eb73243101b92d6ec5a65639615c4da3c44de0bd09bc2b26e33b4517ad5673bf"
)


def _fast_audit_four_packet_claims(
    root: Path, rom: bytes, existing_claims: Iterable[dict[str, Any]]
) -> list[dict[str, Any]]:
    """Promote the four independently verified 2026-09-01 fast-audit packets."""
    from tools.verify_rom_fast_audit_four_packet_coverage import verify as verify_replay

    baseline = list(existing_claims)
    segments = atomize_claims(len(rom), baseline)
    starts = [segment["range"][0] for segment in segments]
    _checked_repository_file(
        root,
        FAST_AUDIT_REPLAY_VERIFIER,
        FAST_AUDIT_REPLAY_VERIFIER_SHA256,
        label="fast-audit immutable-baseline replay verifier",
    )
    replay_report = verify_replay(root)
    if (
        replay_report.get("verified") is not True
        or replay_report.get("packet_count") != 4
        or replay_report.get("promotion_bytes") != 7_140
        or replay_report.get("promotion_claim_count") != 116
    ):
        raise ValueError(
            f"fast-audit immutable-baseline replay failed: {replay_report}"
        )

    def require_unknown(start: int, end: int) -> None:
        index = bisect.bisect_right(starts, start) - 1
        if index < 0:
            raise ValueError("fast-audit packet escaped coverage")
        while start < end:
            segment = segments[index]
            if segment["primary_class"] != "unknown" or segment["range"][0] > start:
                raise ValueError("fast-audit packet is not current unknown")
            start = min(end, segment["range"][1])
            index += 1

    claims: list[dict[str, Any]] = []
    for batch, payload_name, manifest_size, manifest_sha, payload_size, payload_sha, verifier_name, verifier_sha in FAST_AUDIT_FOUR_PACKET_SPECS:
        expected_files = {"manifest.json", payload_name}
        if batch == "rom-sprite-component-source-v1":
            expected_files.add("rom-sprite-component-source.bin")
        artifact = _checked_artifact_directory(root, Path("artifacts") / batch, expected_files, label=f"fast-audit {batch}")
        _checked_repository_file(root, Path(verifier_name), verifier_sha, label=f"fast-audit {batch} verifier")
        manifest_raw = (artifact / "manifest.json").read_bytes()
        payload_raw = (artifact / payload_name).read_bytes()
        if len(manifest_raw) != manifest_size or _sha256(manifest_raw) != manifest_sha or len(payload_raw) != payload_size or _sha256(payload_raw) != payload_sha:
            raise ValueError(f"fast-audit {batch} identity changed")
        payload = json.loads(payload_raw)
        packet_report = replay_report.get("packets", {}).get(batch)
        if not isinstance(packet_report, dict) or packet_report.get("verified") is not True:
            raise ValueError(f"fast-audit {batch} replay result is missing")
        report_sha = packet_report.get("report_sha256")
        if not isinstance(report_sha, str) or len(report_sha) != 64:
            raise ValueError(f"fast-audit {batch} replay report identity is invalid")
        # Selectors address original payload records, not the temporary projection.
        selector_prefix = {
            "rom-event-handler-cfg-v1": "/promotion/semantic_ranges",
            "rom-sprite-component-source-v1": "/classified_ranges",
            "rom-cfg-proven-roots-v16": "/promotion/ranges",
            "rom-cfg-proven-roots-v16-consumed-literals-v1": "/promotion/claims",
        }[batch]
        records: list[tuple[str, list[int], str, str, str]] = []
        if batch == "rom-event-handler-cfg-v1":
            for index, (start, end, kind) in enumerate(payload["promotion"]["semantic_ranges"]):
                primary = "armv4t_event_handler_reachable_thumb_code" if kind == "reachable_thumb_code" else "armv4t_event_handler_consumed_literal_word"
                claim_kind = "event_handler_reachable_instruction_bytes" if kind == "reachable_thumb_code" else "armv4t_event_handler_consumed_literal_word_bytes"
                records.append((f"event-handler-cfg-{index:03d}-{start:06x}", [start, end], primary, claim_kind, _sha256(rom[start:end])))
        elif batch == "rom-sprite-component-source-v1":
            for row in payload["classified_ranges"]:
                records.append((row["id"], row["range"], row["primary_class"], row["claim_kind"], row["bytes_sha256"]))
        elif batch == "rom-cfg-proven-roots-v16":
            for index, interval in enumerate(payload["promotion"]["ranges"]):
                start, end = interval
                records.append((f"cfg-proven-roots-v16-code-{index:03d}-{start:06x}", interval, "armv4t_cfg_proven_roots_v16_reachable_thumb_code", "cfg_proven_roots_v16_reachable_instruction_bytes", _sha256(rom[start:end])))
        else:
            promotion = payload["promotion"]
            for row in promotion["claims"]:
                records.append((row["id"], row["range"], promotion["primary_class"], promotion["claim_kind"], row["bytes_sha256"]))
        for index, (claim_id, interval, primary, claim_kind, bytes_sha) in enumerate(records):
            start, end = interval
            if start >= end or _sha256(rom[start:end]) != bytes_sha:
                raise ValueError(f"fast-audit {batch} range bytes changed")
            require_unknown(start, end)
            claims.append({
                "id": claim_id, "range": [start, end], "role": "primary",
                "primary_class": primary, "claim_kind": claim_kind,
                "promotion_batch": batch, "promoted_from_primary_class": "unknown",
                "baseline_unknown_only": True, "bytes_sha256": bytes_sha,
                "evidence_path": (Path("artifacts") / batch / payload_name).as_posix(),
                "evidence_sha256": payload_sha, "evidence_selector": f"{selector_prefix}/{index}",
                "promotion_manifest_path": (Path("artifacts") / batch / "manifest.json").as_posix(),
                "promotion_manifest_sha256": manifest_sha,
                "independent_verifier_path": verifier_name,
                "independent_verifier_sha256": verifier_sha,
                "independent_verifier_report_sha256": report_sha,
                "immutable_baseline_replay_verifier_path": FAST_AUDIT_REPLAY_VERIFIER.as_posix(),
                "immutable_baseline_replay_verifier_sha256": FAST_AUDIT_REPLAY_VERIFIER_SHA256,
                "runtime_reachability_claimed": False, "loaded_value_semantics_claimed": False,
                "editing_writeback_relocation_safe_claimed": False,
                "free_or_allocatable_space_claimed": False,
                "mode": "thumb" if claim_kind in {
                    "event_handler_reachable_instruction_bytes",
                    "cfg_proven_roots_v16_reachable_instruction_bytes",
                } else None,
            })
    claims.sort(key=lambda claim: (claim["range"], claim["id"]))
    if len(claims) != 116 or sum(c["range"][1] - c["range"][0] for c in claims) != 7_140:
        raise ValueError("fast-audit four-packet denominator changed")
    for previous, current in zip(claims, claims[1:]):
        if previous["range"][1] > current["range"][0]:
            raise ValueError("fast-audit four packets overlap")
    return claims


