def _cfg_proven_roots_v18_claims(
    root: Path, rom: bytes, existing_claims: Iterable[dict[str, Any]]
) -> list[dict[str, Any]]:
    """Project v18 once after an independent raw rebuild."""
    from tools.verify_rom_cfg_proven_roots_v18 import verify_root

    artifact = _checked_artifact_directory(root, CFG_PROVEN_ROOTS_V18_ARTIFACT, {"manifest.json", CFG_PROVEN_ROOTS_V18_PAYLOAD}, label="CFG proven-roots v18")
    verifier_path = _checked_repository_file(root, CFG_PROVEN_ROOTS_V18_VERIFIER, CFG_PROVEN_ROOTS_V18_VERIFIER_SHA256, label="CFG proven-roots v18 verifier")
    manifest_raw = (artifact / "manifest.json").read_bytes()
    payload_raw = (artifact / CFG_PROVEN_ROOTS_V18_PAYLOAD).read_bytes()
    if (len(manifest_raw), _sha256(manifest_raw), len(payload_raw), _sha256(payload_raw)) != (CFG_PROVEN_ROOTS_V18_MANIFEST_SIZE, CFG_PROVEN_ROOTS_V18_MANIFEST_SHA256, CFG_PROVEN_ROOTS_V18_PAYLOAD_SIZE, CFG_PROVEN_ROOTS_V18_PAYLOAD_SHA256):
        raise ValueError("CFG proven-roots v18 artifact identity changed")
    report = verify_root(root, artifact)
    if report.get("verified") is not True or report.get("promotion_bytes") != 1_482 or report.get("preserved_unknown_gap_count") != 4:
        raise ValueError(f"CFG proven-roots v18 independent verification failed: {report}")
    records = json.loads(payload_raw).get("promotion", {}).get("claims")
    if not isinstance(records, list) or len(records) != 17:
        raise ValueError("CFG proven-roots v18 claim denominator changed")
    segments = atomize_claims(len(rom), list(existing_claims)); starts = [row["range"][0] for row in segments]
    def require_unknown(start: int, end: int) -> None:
        index = bisect.bisect_right(starts, start) - 1
        while index >= 0 and start < end:
            segment = segments[index]
            if segment["range"][0] > start or segment["primary_class"] != "unknown": raise ValueError("CFG proven-roots v18 is not current unknown")
            start = min(end, segment["range"][1]); index += 1
        if start < end: raise ValueError("CFG proven-roots v18 escaped coverage")
    report_sha = _sha256(_canonical_json_bytes(report)); claims = []
    for index, row in enumerate(records):
        start, end = row["range"]
        if start >= end or _sha256(rom[start:end]) != row.get("bytes_sha256"): raise ValueError("CFG proven-roots v18 range bytes changed")
        require_unknown(start, end); is_code = row.get("kind") == "reachable_thumb_code"
        if not is_code and row.get("kind") != "consumed_literal_words": raise ValueError("CFG proven-roots v18 semantic kind changed")
        claims.append({
            "id": row["id"], "range": [start, end], "role": "primary",
            "primary_class": "armv4t_cfg_proven_roots_v18_reachable_thumb_code" if is_code else "armv4t_cfg_proven_roots_v18_consumed_literal_word",
            "claim_kind": "cfg_proven_roots_v18_reachable_instruction_bytes" if is_code else "cfg_proven_roots_v18_consumed_literal_word_bytes",
            "promotion_batch": "rom-cfg-proven-roots-v18", "promoted_from_primary_class": "unknown", "baseline_unknown_only": True,
            "bytes_sha256": row["bytes_sha256"], "evidence_path": (CFG_PROVEN_ROOTS_V18_ARTIFACT / CFG_PROVEN_ROOTS_V18_PAYLOAD).as_posix(), "evidence_sha256": CFG_PROVEN_ROOTS_V18_PAYLOAD_SHA256, "evidence_selector": f"/promotion/claims/{index}",
            "promotion_manifest_path": (CFG_PROVEN_ROOTS_V18_ARTIFACT / "manifest.json").as_posix(), "promotion_manifest_sha256": CFG_PROVEN_ROOTS_V18_MANIFEST_SHA256,
            "independent_verifier_path": verifier_path.relative_to(root).as_posix(), "independent_verifier_sha256": CFG_PROVEN_ROOTS_V18_VERIFIER_SHA256, "independent_verifier_report_sha256": report_sha,
            "mode": "thumb" if is_code else None, "runtime_reachability_claimed": False, "loaded_value_semantics_claimed": False, "alignment_gap_classification_claimed": False, "editing_writeback_relocation_safe_claimed": False, "free_or_allocatable_space_claimed": False,
        })
    claims.sort(key=lambda claim: (claim["range"], claim["id"]))
    if sum(b-a for claim in claims for a,b in [claim["range"]]) != 1_482 or any(a["range"][1] > b["range"][0] for a,b in zip(claims,claims[1:])): raise ValueError("CFG proven-roots v18 accounting changed")
    return claims


