def _require_current_unknown_ranges(
    domain_end,
    existing_claims,
    candidate_ranges,
    *,
    label,
):
    """Fail closed if a Tier-1 candidate intersects an existing primary claim.

    This is equivalent to checking the candidate against atomized unknown
    segments, but it stays linear in the claim denominator instead of
    repeatedly constructing every whole-ROM segment for each small packet.
    """

    normalized = list(existing_claims)
    identifiers = [claim.get("id") for claim in normalized]
    if any(not isinstance(value, str) or not value for value in identifiers):
        raise ValueError("every claim must have a non-empty string id")
    if len(set(identifiers)) != len(identifiers):
        raise ValueError("claim ids must be unique")
    primary = []
    for claim in normalized:
        role = claim.get("role")
        if role not in {"primary", "secondary"}:
            raise ValueError(f"claim {claim['id']!r} has an invalid role")
        start, end = _validated_range(claim, domain_end)
        if role == "primary":
            if not isinstance(claim.get("primary_class"), str):
                raise ValueError(f"primary claim {claim['id']!r} has no class")
            primary.append((start, end, claim["id"]))
    primary.sort()
    for left, right in zip(primary, primary[1:]):
        if right[0] < left[1]:
            raise ValueError(
                "conflicting primary claims at "
                f"[0x{right[0]:X}, 0x{min(left[1], right[1]):X}): "
                f"{left[2]}, {right[2]}"
            )
    starts = [row[0] for row in primary]
    for value in candidate_ranges:
        if (
            not isinstance(value, (list, tuple))
            or len(value) != 2
            or not all(isinstance(item, int) for item in value)
        ):
            raise ValueError(f"{label} has an invalid projection range")
        start, end = value
        if start < 0 or start >= end or end > domain_end:
            raise ValueError(f"{label} escaped coverage")
        index = bisect.bisect_right(starts, start) - 1
        if index >= 0 and primary[index][1] > start:
            raise ValueError(f"{label} is not current unknown")
        index += 1
        if index < len(primary) and primary[index][0] < end:
            raise ValueError(f"{label} is not current unknown")


def _project_dependency_packet_claims(root, rom, existing_claims, *, spec, verify_root):
    expected_files = spec.get("files", {"manifest.json", spec["payload"]})
    artifact = _checked_artifact_directory(root, spec["artifact"], expected_files, label=spec["label"])
    verifier_path = _checked_repository_file(root, spec["verifier"], spec["verifier_sha"], label=f'{spec["label"]} verifier')
    manifest_raw = (artifact / "manifest.json").read_bytes(); payload_raw = (artifact / spec["payload"]).read_bytes()
    if (len(manifest_raw), _sha256(manifest_raw), len(payload_raw), _sha256(payload_raw)) != (spec["manifest_size"], spec["manifest_sha"], spec["payload_size"], spec["payload_sha"]):
        raise ValueError(f'{spec["label"]} artifact identity changed')
    report = verify_root(root, artifact)
    if report.get("verified") is not True or report.get("promotion_bytes") != spec["promotion_bytes"]:
        raise ValueError(f'{spec["label"]} independent verification failed: {report}')
    records = json.loads(payload_raw).get("promotion", {}).get("claims")
    if not isinstance(records, list) or len(records) != spec["claim_count"]:
        raise ValueError(f'{spec["label"]} claim denominator changed')
    _require_current_unknown_ranges(
        len(rom),
        existing_claims,
        [row.get("range") for row in records],
        label=spec["label"],
    )
    report_sha = _sha256(_canonical_json_bytes(report)); claims = []
    for index, row in enumerate(records):
        start, end = row["range"]; expected_hash = row.get(spec["hash_field"])
        if start >= end or _sha256(rom[start:end]) != expected_hash: raise ValueError(f'{spec["label"]} range bytes changed')
        if "class_for" in spec:
            primary_class = spec["class_for"](row)
            claim_kind = spec["kind_for"](row)
            mode = spec.get("mode_for", lambda ignored: None)(row)
            if not isinstance(primary_class, str) or not isinstance(claim_kind, str):
                raise ValueError(f'{spec["label"]} semantic kind changed')
        else:
            is_code = spec["is_code"](row)
            if not is_code and not spec["is_literal"](row): raise ValueError(f'{spec["label"]} semantic kind changed')
            primary_class = spec["code_class"] if is_code else spec["literal_class"]
            claim_kind = spec["code_kind"] if is_code else spec["literal_kind"]
            mode = "thumb" if is_code else None
        claims.append({
            "id": row["id"], "range": [start, end], "role": "primary",
            "primary_class": primary_class,
            "claim_kind": claim_kind,
            "promotion_batch": spec["batch"], "promoted_from_primary_class": "unknown", "baseline_unknown_only": True,
            "bytes_sha256": expected_hash, "evidence_path": (spec["artifact"] / spec["payload"]).as_posix(), "evidence_sha256": spec["payload_sha"], "evidence_selector": f"/promotion/claims/{index}",
            "promotion_manifest_path": (spec["artifact"] / "manifest.json").as_posix(), "promotion_manifest_sha256": spec["manifest_sha"],
            "independent_verifier_path": verifier_path.relative_to(root).as_posix(), "independent_verifier_sha256": spec["verifier_sha"], "independent_verifier_report_sha256": report_sha,
            "mode": mode, "runtime_reachability_claimed": False, "loaded_value_semantics_claimed": False, "alignment_gap_classification_claimed": False, "editing_writeback_relocation_safe_claimed": False, "free_or_allocatable_space_claimed": False,
        })
    claims.sort(key=lambda claim: (claim["range"], claim["id"]))
    if sum(b-a for claim in claims for a,b in [claim["range"]]) != spec["promotion_bytes"] or any(a["range"][1] > b["range"][0] for a,b in zip(claims,claims[1:])):
        raise ValueError(f'{spec["label"]} accounting changed')
    return claims


def _boot_interwork_continuation_claims(root, rom, existing_claims):
    from tools.verify_rom_boot_interwork_continuation import verify_root
