def _boot_copy_source_claims(root, rom, existing_claims):
    from tools.verify_rom_boot_copy_sources import verify_artifact

    artifact = _checked_artifact_directory(
        root,
        BOOT_COPY_SOURCES_ARTIFACT,
        {"manifest.json", BOOT_COPY_SOURCES_PAYLOAD},
        label="boot copy sources",
    )
    _checked_repository_file(
        root,
        BOOT_COPY_SOURCES_VERIFIER,
        BOOT_COPY_SOURCES_VERIFIER_SHA256,
        label="boot copy sources verifier",
    )
    manifest_raw = (artifact / "manifest.json").read_bytes()
    payload_raw = (artifact / BOOT_COPY_SOURCES_PAYLOAD).read_bytes()
    if (
        len(manifest_raw),
        _sha256(manifest_raw),
        len(payload_raw),
        _sha256(payload_raw),
    ) != (
        BOOT_COPY_SOURCES_MANIFEST_SIZE,
        BOOT_COPY_SOURCES_MANIFEST_SHA256,
        BOOT_COPY_SOURCES_PAYLOAD_SIZE,
        BOOT_COPY_SOURCES_PAYLOAD_SHA256,
    ):
        raise ValueError("boot copy sources artifact identity changed")
    report = verify_artifact(root, artifact)
    if (
        report.get("verified") is not True
        or report.get("contract_ok") is not True
        or report.get("promotion_bytes") != 620
        or report.get("copy_operation_count") != 5
        or report.get("dma_descriptor_count") != 9
        or report.get("upstream_boot_verified") is not True
        or report.get("upstream_v12_verified") is not True
    ):
        raise ValueError(f"boot copy sources independent verification failed: {report}")
    payload = json.loads(payload_raw)
    promotion = payload.get("promotion", {})
    start, end = promotion.get("range", [None, None])
    if (
        [start, end] != [0x4C8, 0x734]
        or promotion.get("bytes") != 620
        or promotion.get("bytes_sha256")
        != "0be5228ec171480a4097db134e32c030972f43fbf637a425f3f4826450944e80"
        or promotion.get("primary_class") != "boot_fixed_rom_copy_source_bytes"
        or promotion.get("claim_kind") != "fixed_rom_copy_source_bytes"
        or promotion.get("promotion_batch") != "rom-boot-copy-sources-v1"
        or _sha256(rom[start:end]) != promotion["bytes_sha256"]
    ):
        raise ValueError("boot copy sources promotion contract changed")
    segments = atomize_claims(len(rom), list(existing_claims))
    intersections = [
        segment
        for segment in segments
        if segment["range"][0] < end and start < segment["range"][1]
    ]
    cursor = start
    for segment in intersections:
        if segment["range"][0] > cursor or segment["primary_class"] != "unknown":
            raise ValueError("boot copy sources are not current unknown")
        cursor = max(cursor, min(end, segment["range"][1]))
    if cursor != end:
        raise ValueError("boot copy sources escaped current coverage")
    return [
        {
            "id": "boot-fixed-rom-copy-source-0004c8",
            "range": [start, end],
            "role": "primary",
            "primary_class": promotion["primary_class"],
            "claim_kind": promotion["claim_kind"],
            "bytes_sha256": promotion["bytes_sha256"],
            "promotion_batch": promotion["promotion_batch"],
            "promoted_from_primary_class": "unknown",
            "baseline_unknown_only": True,
            "current_unknown_verified_by_auditor": True,
            "coverage_projection_gate": "current_unknown_before_projection",
            "evidence_path": (BOOT_COPY_SOURCES_ARTIFACT / BOOT_COPY_SOURCES_PAYLOAD).as_posix(),
            "evidence_sha256": BOOT_COPY_SOURCES_PAYLOAD_SHA256,
            "promotion_manifest_path": (BOOT_COPY_SOURCES_ARTIFACT / "manifest.json").as_posix(),
            "promotion_manifest_sha256": BOOT_COPY_SOURCES_MANIFEST_SHA256,
            "independent_verifier_path": BOOT_COPY_SOURCES_VERIFIER.as_posix(),
            "independent_verifier_sha256": BOOT_COPY_SOURCES_VERIFIER_SHA256,
            "independent_verifier_report_sha256": _sha256(_canonical_json_bytes(report)),
            "copy_operation_count": 5,
            "dma_descriptor_denominator_count": 9,
            "arm_code_semantics_claimed": False,
            "natural_runtime_reachability_claimed": False,
            "business_semantics_claimed": False,
            "editing_or_relocation_safety_claimed": False,
            "allocatable_space_claimed": False,
            "adjacent_boot_bytes_claimed": False,
        }
    ]


def _text_bg_task_closure_claims(root, rom, existing_claims):
    """Project only exact current-unknown bytes from the frozen task closure."""

    from tools.verify_rom_text_bg_task_closure import verify_artifact

    artifact = _checked_artifact_directory(
        root,
        TEXT_BG_TASK_CLOSURE_ARTIFACT,
        {"manifest.json", TEXT_BG_TASK_CLOSURE_PAYLOAD},
        label="text-BG task closure",
    )
    verifier_path = _checked_repository_file(
        root,
        TEXT_BG_TASK_CLOSURE_VERIFIER,
        TEXT_BG_TASK_CLOSURE_VERIFIER_SHA256,
        label="text-BG task closure verifier",
    )
    manifest_raw = (artifact / "manifest.json").read_bytes()
    payload_raw = (artifact / TEXT_BG_TASK_CLOSURE_PAYLOAD).read_bytes()
    if (
        len(manifest_raw), _sha256(manifest_raw), len(payload_raw), _sha256(payload_raw)
    ) != (
        TEXT_BG_TASK_CLOSURE_MANIFEST_SIZE,
        TEXT_BG_TASK_CLOSURE_MANIFEST_SHA256,
        TEXT_BG_TASK_CLOSURE_PAYLOAD_SIZE,
        TEXT_BG_TASK_CLOSURE_PAYLOAD_SHA256,
    ):
        raise ValueError("text-BG task closure artifact identity changed")
    report = verify_artifact(root, artifact)
    if (
        report.get("verified") is not True
        or report.get("contract_ok") is not True
        or report.get("root_count") != 10
        or report.get("instruction_count") != 1330
        or report.get("promotion_bytes") != 2940
        or report.get("frontier_count") != 0
    ):
        raise ValueError(f"text-BG task closure independent verification failed: {report}")
    payload = json.loads(payload_raw)
    promotion = payload.get("promotion", {})
    code_ranges = promotion.get("code_ranges")
    literal_ranges = promotion.get("literal_ranges")
    if (
        not isinstance(code_ranges, list)
        or len(code_ranges) != 21
        or not isinstance(literal_ranges, list)
        or len(literal_ranges) != 13
        or promotion.get("code_bytes") != 2692
        or promotion.get("literal_bytes") != 248
        or promotion.get("promotion_bytes") != 2940
        or promotion.get("code_primary_class")
        != "armv4t_text_bg_task_dependency_closure_thumb_code"
        or promotion.get("literal_primary_class")
        != "armv4t_text_bg_task_dependency_closure_consumed_literal_word"
        or promotion.get("promotion_batch") != "rom-text-bg-task-closure-v1"
        or promotion.get("promoted_from_primary_class") != "unknown"
        or _sha256(b"".join(rom[start:end] for start, end in code_ranges))
        != promotion.get("code_bytes_sha256")
        or _sha256(b"".join(rom[start:end] for start, end in literal_ranges))
        != promotion.get("literal_bytes_sha256")
    ):
        raise ValueError("text-BG task closure promotion contract changed")
    prior = list(existing_claims)
    dependencies = {
        (tuple(claim.get("range", [])), claim.get("primary_class"))
        for claim in prior
        if claim.get("role") == "primary"
    }
    required = {
        ((0x08ACC8, 0x08ACF2), "armv4t_text_bg_loop_continuation_reachable_thumb_code"),
        ((0x08AEB4, 0x08AEC0), "armv4t_text_bg_loop_continuation_consumed_literal_word"),
        ((0x08ACF2, 0x08AD08), "consumer_code_slice"),
        ((0x08AD30, 0x08AD4A), "consumer_code_slice"),
    }
    if not required <= dependencies:
        raise ValueError("text-BG task closure dependency owner mismatch")
    segments = atomize_claims(len(rom), prior)
    starts = [segment["range"][0] for segment in segments]

    def require_unknown(start, end):
        index = bisect.bisect_right(starts, start) - 1
        cursor = start
        while 0 <= index < len(segments) and cursor < end:
            segment = segments[index]
            if segment["range"][0] > cursor or segment["primary_class"] != "unknown":
                raise ValueError("text-BG task closure range is not current unknown")
            cursor = min(end, segment["range"][1])
            index += 1
        if cursor != end:
            raise ValueError("text-BG task closure range escaped coverage")

    report_sha = _sha256(_canonical_json_bytes(report))
    claims = []
    rows = [
        ("code", index, interval)
        for index, interval in enumerate(code_ranges)
    ] + [
        ("literal", index, interval)
        for index, interval in enumerate(literal_ranges)
    ]
    for kind, index, interval in rows:
        start, end = interval
        require_unknown(start, end)
        is_code = kind == "code"
        claims.append({
            "id": f"text-bg-task-closure-{kind}-{start:06x}",
            "range": [start, end],
            "role": "primary",
            "primary_class": (
                promotion["code_primary_class"] if is_code else promotion["literal_primary_class"]
            ),
            "claim_kind": (
                "text_bg_task_closure_reachable_instruction_bytes"
                if is_code else "text_bg_task_closure_consumed_literal_word_bytes"
            ),
            "mode": "thumb" if is_code else None,
            "bytes_sha256": _sha256(rom[start:end]),
            "promotion_batch": promotion["promotion_batch"],
            "promoted_from_primary_class": "unknown",
            "baseline_unknown_only": True,
            "current_unknown_verified_by_auditor": True,
            "coverage_projection_gate": "current_unknown_before_projection",
            "dependency_owners_verified_by_auditor": True,
            "evidence_path": (TEXT_BG_TASK_CLOSURE_ARTIFACT / TEXT_BG_TASK_CLOSURE_PAYLOAD).as_posix(),
            "evidence_sha256": TEXT_BG_TASK_CLOSURE_PAYLOAD_SHA256,
            "evidence_selector": f"/promotion/{kind}_ranges/{index}",
            "promotion_manifest_path": (TEXT_BG_TASK_CLOSURE_ARTIFACT / "manifest.json").as_posix(),
            "promotion_manifest_sha256": TEXT_BG_TASK_CLOSURE_MANIFEST_SHA256,
            "independent_verifier_path": verifier_path.relative_to(root).as_posix(),
            "independent_verifier_sha256": TEXT_BG_TASK_CLOSURE_VERIFIER_SHA256,
            "independent_verifier_report_sha256": report_sha,
            "whole_program_natural_runtime_claimed": False,
            "business_semantics_claimed": False,
            "adjacent_padding_free_space_claimed": False,
            "editing_or_relocation_safety_claimed": False,
        })
    claims.sort(key=lambda claim: (claim["range"], claim["id"]))
    if (
        len(claims) != 34
        or sum(claim["range"][1] - claim["range"][0] for claim in claims) != 2940
        or any(left["range"][1] > right["range"][0] for left, right in zip(claims, claims[1:]))
    ):
        raise ValueError("text-BG task closure claim accounting changed")
    return claims


