def _scene_source_closure_claims(root, rom, existing_claims):
    """Project the frozen parser/OBJ source closures without a full audit."""

    from tools.verify_rom_scene_source_closures import verify_artifact

    root = Path(root).resolve(strict=True)
    artifact = _checked_artifact_directory(
        root,
        SCENE_SOURCE_CLOSURES_ARTIFACT,
        {"manifest.json", SCENE_SOURCE_CLOSURES_PAYLOAD},
        label="scene source closures artifact",
    )
    manifest_path = _checked_repository_file(
        root,
        SCENE_SOURCE_CLOSURES_ARTIFACT / "manifest.json",
        SCENE_SOURCE_CLOSURES_MANIFEST_SHA256,
        expected_size=SCENE_SOURCE_CLOSURES_MANIFEST_SIZE,
        label="scene source closures manifest",
    )
    payload_path = _checked_repository_file(
        root,
        SCENE_SOURCE_CLOSURES_ARTIFACT / SCENE_SOURCE_CLOSURES_PAYLOAD,
        SCENE_SOURCE_CLOSURES_PAYLOAD_SHA256,
        expected_size=SCENE_SOURCE_CLOSURES_PAYLOAD_SIZE,
        label="scene source closures payload",
    )
    verifier_path = _checked_repository_file(
        root,
        SCENE_SOURCE_CLOSURES_VERIFIER,
        SCENE_SOURCE_CLOSURES_VERIFIER_SHA256,
        label="scene source closures verifier",
    )
    manifest_raw = manifest_path.read_bytes()
    payload_raw = payload_path.read_bytes()
    try:
        manifest = json.loads(manifest_raw)
        payload = json.loads(payload_raw)
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise ValueError("scene source closures JSON is invalid") from error
    if manifest_raw != _canonical_json_bytes(manifest) \
            or payload_raw != _canonical_json_bytes(payload):
        raise ValueError("scene source closures JSON is not canonical")
    if manifest.get("schema") != "git-artifact-promotion-v1" \
            or manifest.get("artifact_schema") != "rom-scene-source-closures-v1" \
            or manifest.get("artifact_status") != "accepted" \
            or manifest.get("canonical_destination") \
            != SCENE_SOURCE_CLOSURES_ARTIFACT.as_posix() \
            or manifest.get("files") != {
                SCENE_SOURCE_CLOSURES_PAYLOAD: {
                    "sha256": SCENE_SOURCE_CLOSURES_PAYLOAD_SHA256,
                    "size": SCENE_SOURCE_CLOSURES_PAYLOAD_SIZE,
                }
            }:
        raise ValueError("scene source closures manifest changed")
    report = verify_artifact(root, artifact)
    if report.get("verified") is not True \
            or report.get("promotion_bytes") != 1_015 \
            or report.get("promotion_claim_count") != 73:
        raise ValueError(
            "scene source closures independent verification failed: "
            f"{report}"
        )
    promotion = payload.get("promotion")
    records = promotion.get("claims") if isinstance(promotion, dict) else None
    if not isinstance(records, list) or len(records) != 73 \
            or promotion.get("bytes") != 1_015 \
            or promotion.get("obj_claim_count") != 2 \
            or promotion.get("obj_bytes") != 360 \
            or promotion.get("source_claim_count") != 71 \
            or promotion.get("source_bytes") != 655:
        raise ValueError("scene source closures promotion changed")
    allowed = {
        "scene_obj_source_closure": "scene_obj_source_closure_bytes",
        "parser_bound_scene_source_record": (
            "parser_bound_scene_source_record_bytes"
        ),
    }
    candidate_ranges = []
    for index, record in enumerate(records):
        if not isinstance(record, dict):
            raise ValueError("scene source closures claim changed")
        start, end = record.get("range", [None, None])
        primary_class = record.get("primary_class")
        if record.get("kind") != primary_class \
                or primary_class not in allowed \
                or record.get("baseline_unknown_only") is not True \
                or record.get("bytes_sha256") != _sha256(rom[start:end]) \
                or not isinstance(record.get("id"), str) \
                or not isinstance(start, int) or not isinstance(end, int) \
                or not 0 <= start < end <= len(rom):
            raise ValueError(
                f"scene source closures claim {index} changed"
            )
        candidate_ranges.append([start, end])
    _require_current_unknown_ranges(
        len(rom), existing_claims, candidate_ranges,
        label="scene source closures",
    )
    evidence_path = (
        SCENE_SOURCE_CLOSURES_ARTIFACT / SCENE_SOURCE_CLOSURES_PAYLOAD
    ).as_posix()
    report_sha = _sha256(_canonical_json_bytes(report))
    claims = []
    for index, record in enumerate(records):
        start, end = record["range"]
        primary_class = record["primary_class"]
        claims.append({
            "id": f"scene-source-closure-{index:02d}-{start:06x}",
            "range": [start, end],
            "role": "primary",
            "primary_class": primary_class,
            "claim_kind": allowed[primary_class],
            "promotion_batch": "rom-scene-source-closures-v1",
            "promoted_from_primary_class": "unknown",
            "baseline_unknown_only": True,
            "current_unknown_verified_by_auditor": True,
            "coverage_projection_gate": "current_unknown_before_projection",
            "bytes_sha256": record["bytes_sha256"],
            "evidence_path": evidence_path,
            "evidence_sha256": SCENE_SOURCE_CLOSURES_PAYLOAD_SHA256,
            "evidence_selector": f"/promotion/claims/{index}",
            "promotion_manifest_path": (
                SCENE_SOURCE_CLOSURES_ARTIFACT / "manifest.json"
            ).as_posix(),
            "promotion_manifest_sha256": (
                SCENE_SOURCE_CLOSURES_MANIFEST_SHA256
            ),
            "independent_verifier_path": verifier_path.relative_to(root).as_posix(),
            "independent_verifier_sha256": (
                SCENE_SOURCE_CLOSURES_VERIFIER_SHA256
            ),
            "independent_verifier_report_sha256": report_sha,
            "accepted_literal_consumer_owner_verified": True,
            "parser_terminator_verified": (
                primary_class == "parser_bound_scene_source_record"
            ),
            "obj_structure_verified": (
                primary_class == "scene_obj_source_closure"
            ),
            "natural_runtime_reachability_claimed": False,
            "translated_text_semantics_claimed": False,
            "alignment_gap_classification_claimed": False,
            "editing_writeback_relocation_safe_claimed": False,
            "free_or_allocatable_space_claimed": False,
        })
    claims.sort(key=lambda claim: (claim["range"], claim["id"]))
    if len(claims) != 73 \
            or sum(claim["range"][1] - claim["range"][0]
                   for claim in claims) != 1_015 \
            or any(left["range"][1] > right["range"][0]
                   for left, right in zip(claims, claims[1:])):
        raise ValueError("scene source closures accounting changed")
    return claims


def _story_callback_dependency_claims(root, rom, existing_claims):
    """Project the frozen story-callback direct dependency closures."""

    from tools.verify_rom_story_callback_dependency_closures import verify_artifact

    classes = {
        "reachable_thumb_code": (
            "armv4t_story_callback_dependency_reachable_thumb_code",
            "story_callback_dependency_reachable_instruction_bytes",
            "thumb",
        ),
        "consumed_literal_words": (
            "story_callback_dependency_consumed_literal_word",
            "story_callback_dependency_consumed_literal_word_bytes",
            None,
        ),
    }

    def semantic(row, index):
        try:
            return classes[row.get("kind")][index]
        except KeyError as error:
            raise ValueError(
                "story callback dependency semantic kind changed"
            ) from error

    spec = {
        "label": "story callback dependency closures",
        "artifact": STORY_CALLBACK_DEPENDENCY_ARTIFACT,
        "payload": STORY_CALLBACK_DEPENDENCY_PAYLOAD,
        "manifest_size": STORY_CALLBACK_DEPENDENCY_MANIFEST_SIZE,
        "manifest_sha": STORY_CALLBACK_DEPENDENCY_MANIFEST_SHA256,
        "payload_size": STORY_CALLBACK_DEPENDENCY_PAYLOAD_SIZE,
        "payload_sha": STORY_CALLBACK_DEPENDENCY_PAYLOAD_SHA256,
        "verifier": STORY_CALLBACK_DEPENDENCY_VERIFIER,
        "verifier_sha": STORY_CALLBACK_DEPENDENCY_VERIFIER_SHA256,
        "promotion_bytes": 1_932,
        "claim_count": 32,
        "batch": "rom-story-callback-dependency-closures-v1",
        "hash_field": "bytes_sha256",
        "class_for": lambda row: semantic(row, 0),
        "kind_for": lambda row: semantic(row, 1),
        "mode_for": lambda row: semantic(row, 2),
    }
    claims = _project_dependency_packet_claims(
        root,
        rom,
        existing_claims,
        spec=spec,
        verify_root=lambda verifier_root, artifact: verify_artifact(
            verifier_root, artifact
        ),
    )
    for claim in claims:
        claim["current_unknown_verified_by_auditor"] = True
        claim["coverage_projection_gate"] = "current_unknown_before_projection"
        claim["root_producer_denominator_verified"] = True
        claim["recursive_dependency_closure_verified"] = True
        claim["opaque_exit_ownership_verified"] = True
        claim["structured_return_contract_verified"] = True
        claim["preserved_unknown_holes_verified"] = True
        claim["natural_runtime_reachability_claimed"] = False
        claim["all_callback_dependencies_exhausted_claimed"] = False
    return claims


