def audit_manifest(root: Path, manifest: dict[str, Any]) -> dict[str, Any]:
    _require_supported_python()
    errors: list[str] = []
    try:
        expected = build_manifest(root)
    except (OSError, ValueError, json.JSONDecodeError) as error:
        return {
            "schema": "rom-byte-coverage-audit-v1",
            "verified": False,
            "semantic_classification_complete": False,
            "errors": [str(error)],
        }
    if manifest != expected:
        errors.append("manifest differs from reproducible scan")
    return {
        "schema": "rom-byte-coverage-audit-v1",
        "verified": not errors,
        "state_inventory_complete": expected["state_inventory_complete"],
        "semantic_classification_complete": expected[
            "semantic_classification_complete"
        ],
        "summary": expected["summary"],
        "errors": errors,
    }


def _write_manifest_atomic(path: Path, manifest: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(f".{path.name}.{os.getpid()}.tmp")
    try:
        temporary.write_text(
            json.dumps(manifest, ensure_ascii=False, indent=2, sort_keys=True)
            + "\n",
            encoding="utf-8",
        )
        os.replace(temporary, path)
    finally:
        temporary.unlink(missing_ok=True)


def _report_from_built_manifest(
    manifest: dict[str, Any], *, errors: list[str]
) -> dict[str, Any]:
    return {
        "schema": "rom-byte-coverage-audit-v1",
        "verified": not errors,
        "state_inventory_complete": manifest["state_inventory_complete"],
        "semantic_classification_complete": manifest[
            "semantic_classification_complete"
        ],
        "summary": manifest["summary"],
        "errors": errors,
    }


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root", type=Path, default=Path.cwd())
    parser.add_argument(
        "--manifest",
        type=Path,
        default=Path("sequel/rom-byte-coverage.json"),
    )
    parser.add_argument("--write", action="store_true")
    parser.add_argument(
        "--require-semantic-complete",
        action="store_true",
        help="return 2 when the manifest is reproducible but any ROM byte remains unknown",
    )
    args = parser.parse_args(argv)
    manifest_path = args.manifest
    if not manifest_path.is_absolute():
        manifest_path = args.root / manifest_path
    if args.write:
        manifest = build_manifest(args.root)
        _write_manifest_atomic(manifest_path, manifest)
        try:
            readback = json.loads(manifest_path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError) as error:
            report = _report_from_built_manifest(
                manifest, errors=[f"written manifest could not be read back: {error}"]
            )
        else:
            report = _report_from_built_manifest(
                manifest,
                errors=(
                    []
                    if readback == manifest
                    else ["written manifest differs from the built manifest"]
                ),
            )
    else:
        try:
            manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError) as error:
            print(
                json.dumps(
                    {
                        "schema": "rom-byte-coverage-audit-v1",
                        "verified": False,
                        "errors": [str(error)],
                    },
                    indent=2,
                    sort_keys=True,
                )
            )
            return 1
        report = audit_manifest(args.root, manifest)
    print(json.dumps(report, ensure_ascii=False, indent=2, sort_keys=True))
    if not report["verified"]:
        return 1
    if args.require_semantic_complete and not report.get(
        "semantic_classification_complete"
    ):
        return 2
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
